/**
 * InstanceManager - mpv 實例管理
 *
 * 直接在 Renderer 進程中運行 MpvController，提供高效能視頻播放。
 *
 * 前提條件：
 * - Electron 設定 nodeIntegration: true
 * - Electron 設定 contextIsolation: false
 */

import {
    NativeController,
    isNativeModuleAvailable,
    type VideoEvent,
    type FrameData,
    type FrameMetadata,
    type VideoState,
    type TargetResolution,
} from '../../native';

export type { VideoEvent, FrameData, FrameMetadata, VideoState, TargetResolution };

/**
 * 實例創建選項
 */
export interface InstanceOptions {
    /** 硬體解碼模式（省略則使用平台預設值：Windows=d3d11va-copy, macOS=auto-safe） */
    hwdec?: string;
}

/**
 * 實例管理器配置
 */
export interface InstanceManagerConfig {
    /** 實例 ID */
    instanceId: string;
    /** 實例創建選項 */
    instanceOptions?: InstanceOptions;
    /** 視頻事件處理器 */
    onVideoEvent?: (event: VideoEvent) => void;
}

/**
 * InstanceManager - 直連模式實例管理器
 *
 * 直接在 Renderer 進程中管理 MpvController 實例，
 * 消除 IPC 帶寬瓶頸。
 */
export class InstanceManager {
    private readonly instanceId: string;
    private config: InstanceManagerConfig;

    // Native 控制器
    private controller: NativeController | null = null;
    private controllerInitPromise: Promise<boolean> | null = null;
    private currentHwdec: string | undefined;

    // 事件訂閱
    private eventUnsubscribe: (() => void) | null = null;

    // 斷開連接生命週期
    private disconnectCleanupTimer: ReturnType<typeof setTimeout> | null = null;
    private wasPlayingBeforeDisconnect = false;
    private static readonly DISCONNECT_CLEANUP_DELAY_MS = 5000;

    // 追蹤所有實例
    private static allInstances: Set<InstanceManager> = new Set();
    private static beforeUnloadRegistered = false;

    /**
     * 檢查直連模式是否可用
     */
    static isAvailable(): boolean {
        return isNativeModuleAvailable();
    }

    /**
     * 註冊 beforeunload 監聽器
     */
    private static registerBeforeUnload(): void {
        if (this.beforeUnloadRegistered) return;
        this.beforeUnloadRegistered = true;

        window.addEventListener('beforeunload', () => {
            console.log(`[InstanceManager] beforeunload: destroying ${this.allInstances.size} instances`);

            const instances = Array.from(this.allInstances);
            for (const instance of instances) {
                try {
                    instance.destroySync();
                } catch (error) {
                    console.error('[InstanceManager] Failed to destroy instance on beforeunload:', error);
                }
            }
        });

        console.log('[InstanceManager] beforeunload handler registered');
    }

    constructor(config: InstanceManagerConfig) {
        this.instanceId = config.instanceId;
        this.config = config;
        this.currentHwdec = config.instanceOptions?.hwdec;

        InstanceManager.allInstances.add(this);
        InstanceManager.registerBeforeUnload();
    }

    /**
     * 更新配置
     */
    updateConfig(config: Partial<InstanceManagerConfig>): void {
        this.config = { ...this.config, ...config };

        // 如果有新的事件處理器，重新訂閱
        if (config.onVideoEvent && this.controller) {
            this.unsubscribeEvents();
            this.subscribeEvents();
        }
    }

    /**
     * 獲取實例 ID
     */
    getInstanceId(): string {
        return this.instanceId;
    }

    /**
     * 檢查實例是否已創建
     */
    isCreated(): boolean {
        return this.controller !== null && !this.controller.isDestroyed();
    }

    /**
     * 確保實例存在（懶加載）
     */
    async ensureInstance(): Promise<boolean> {
        if (this.controller && !this.controller.isDestroyed()) {
            return true;
        }

        if (this.controllerInitPromise) {
            return this.controllerInitPromise;
        }

        this.controllerInitPromise = this.createControllerInternal();
        return this.controllerInitPromise;
    }

    /**
     * 獲取當前 hwdec 設定
     */
    getCurrentHwdec(): string | undefined {
        return this.currentHwdec;
    }

    /**
     * 檢查是否需要重建
     */
    needsRecreate(newHwdec: string | undefined): boolean {
        return this.isCreated() && newHwdec !== this.currentHwdec;
    }

    /**
     * 重建實例
     */
    async recreate(options?: InstanceOptions): Promise<boolean> {
        if (this.controller) {
            await this.destroy();
        }
        if (options?.hwdec !== undefined) {
            this.currentHwdec = options.hwdec;
        }
        return this.ensureInstance();
    }

    /**
     * 內部方法：創建控制器
     */
    private async createControllerInternal(): Promise<boolean> {
        try {
            this.controller = new NativeController({
                hwdec: this.currentHwdec,
            });

            // 確保初始狀態正確：精準 seek 模式（hr-seek=yes）
            // 這是第一次載入影片正常運作的關鍵
            this.controller.setFastSeek(false);

            this.subscribeEvents();

            console.log(`[InstanceManager] Instance created: ${this.instanceId} (hwdec: ${this.currentHwdec})`);
            return true;
        } catch (error) {
            console.error(`[InstanceManager] Failed to create instance:`, error);
            this.controllerInitPromise = null;
            return false;
        }
    }

    /**
     * 訂閱事件
     */
    private subscribeEvents(): void {
        if (!this.controller || !this.config.onVideoEvent) return;

        this.eventUnsubscribe = this.controller.onEvent(this.config.onVideoEvent);
    }

    /**
     * 取消事件訂閱
     */
    unsubscribeEvents(): void {
        if (this.eventUnsubscribe) {
            this.eventUnsubscribe();
            this.eventUnsubscribe = null;
        }
    }

    /**
     * 銷毀實例
     */
    async destroy(): Promise<void> {
        InstanceManager.allInstances.delete(this);
        this.cancelScheduledCleanup();
        this.unsubscribeEvents();

        if (this.controller) {
            this.controller.destroy();
            this.controller = null;
        }

        this.controllerInitPromise = null;
        console.log(`[InstanceManager] Instance destroyed: ${this.instanceId}`);
    }

    /**
     * 同步銷毀
     */
    private destroySync(): void {
        InstanceManager.allInstances.delete(this);
        this.cancelScheduledCleanup();
        this.unsubscribeEvents();

        if (this.controller) {
            this.controller.destroy();
            this.controller = null;
        }

        this.controllerInitPromise = null;
    }

    // ===== 斷開連接生命週期管理 =====

    handleDisconnect(wasPaused: boolean): void {
        if (!this.controller) return;

        this.wasPlayingBeforeDisconnect = !wasPaused;

        if (!wasPaused) {
            this.controller.pause();
        }

        this.scheduleCleanup();
        console.log(`[InstanceManager] Disconnected, cleanup scheduled: ${this.instanceId}`);
    }

    handleReconnect(): boolean {
        const wasCancelled = this.cancelScheduledCleanup();

        if (wasCancelled) {
            console.log(`[InstanceManager] Reconnected before cleanup: ${this.instanceId}`);
        }

        const shouldResume = this.wasPlayingBeforeDisconnect;
        this.wasPlayingBeforeDisconnect = false;
        return shouldResume;
    }

    handleDisconnectImmediate(wasPaused: boolean): void {
        if (!this.controller) return;

        this.wasPlayingBeforeDisconnect = !wasPaused;
        this.unsubscribeEvents();

        if (!wasPaused) {
            this.controller.pause();
        }

        this.scheduleCleanup();
        console.log(`[InstanceManager] Disconnected immediately: ${this.instanceId}`);
    }

    private scheduleCleanup(): void {
        if (this.disconnectCleanupTimer) return;

        this.disconnectCleanupTimer = setTimeout(() => {
            this.disconnectCleanupTimer = null;

            if (this.controller) {
                console.log(`[InstanceManager] Disconnect cleanup timeout: ${this.instanceId}`);
                this.destroy();
            }
        }, InstanceManager.DISCONNECT_CLEANUP_DELAY_MS);
    }

    private cancelScheduledCleanup(): boolean {
        if (this.disconnectCleanupTimer) {
            clearTimeout(this.disconnectCleanupTimer);
            this.disconnectCleanupTimer = null;
            return true;
        }
        return false;
    }

    // ===== 視頻控制 API（直接調用，不走 IPC）=====

    load(src: string): boolean {
        if (!this.controller) return false;
        return this.controller.loadFile(src);
    }

    play(): boolean {
        if (!this.controller) return false;
        return this.controller.play();
    }

    pause(): boolean {
        if (!this.controller) return false;
        return this.controller.pause();
    }

    seek(position: number, mode: 'absolute' | 'relative' = 'absolute'): boolean {
        if (!this.controller) return false;
        return this.controller.seek(position, mode);
    }

    togglePlay(): boolean {
        if (!this.controller) return false;
        return this.controller.togglePlay();
    }

    getState(): VideoState | null {
        if (!this.controller) return null;
        return this.controller.getState();
    }

    getPosition(): number {
        if (!this.controller) return 0;
        return this.controller.getPosition();
    }

    getDuration(): number {
        if (!this.controller) return 0;
        return this.controller.getDuration();
    }

    isPaused(): boolean {
        if (!this.controller) return true;
        return this.controller.isPaused();
    }

    setVolume(volume: number): boolean {
        if (!this.controller) return false;
        return this.controller.setVolume(volume);
    }

    setSpeed(speed: number): boolean {
        if (!this.controller) return false;
        return this.controller.setSpeed(speed);
    }

    setMute(muted: boolean): boolean {
        if (!this.controller) return false;
        return this.controller.setMute(muted);
    }

    getMute(): boolean {
        if (!this.controller) return false;
        return this.controller.getMute();
    }

    setLoop(loop: boolean): boolean {
        if (!this.controller) return false;
        return this.controller.setLoop(loop);
    }

    getLoop(): boolean {
        if (!this.controller) return false;
        return this.controller.getLoop();
    }

    setFastSeek(enabled: boolean): boolean {
        if (!this.controller) return false;
        return this.controller.setFastSeek(enabled);
    }

    /**
     * 設置目標渲染分辨率
     *
     * 透過 mpv vf scale 濾鏡在解碼時縮放，比渲染後縮放更高效。
     * 與性能監控的 throughput_scale 協同工作。
     */
    setTargetResolution(width: number, height: number): boolean {
        if (!this.controller) return false;
        return this.controller.setTargetResolution(width, height);
    }

    // ===== 幀渲染（核心優勢：直接調用，無 IPC）=====

    /**
     * 渲染一幀
     *
     * 這是直連模式的核心優勢：直接在 Renderer 進程調用 native 渲染，
     * 無需 IPC 傳輸幀數據。
     */
    renderFrame(targetWidth?: number, targetHeight?: number): FrameData | null {
        if (!this.controller) return null;
        return this.controller.renderFrame(targetWidth, targetHeight);
    }

    /**
     * 獲取幀元數據
     */
    getFrameMetadata(): FrameMetadata | null {
        if (!this.controller) return null;
        return this.controller.getFrameMetadata();
    }

    /**
     * 獲取視頻尺寸
     */
    getVideoSize(): {
        width: number;
        height: number;
        rotation: number;
        renderWidth: number;
        renderHeight: number;
        fps: number;
        format: 'rgba' | 'yuv420';
    } | null {
        if (!this.controller) return null;
        return this.controller.getVideoSize();
    }

    // ===== 元數據和 HDR =====

    getMetadata() {
        if (!this.controller) return null;
        return this.controller.getMetadata();
    }

    getHdrInfo() {
        if (!this.controller) return null;
        return this.controller.getHdrInfo();
    }

    setHdrMode(enabled: boolean): boolean {
        if (!this.controller) return false;
        return this.controller.setHdrMode(enabled);
    }

    // ===== 其他 =====

    requestScreenshot(time: number): boolean {
        if (!this.controller) return false;
        return this.controller.requestScreenshot(time);
    }

    /**
     * 訂閱視頻事件
     *
     * 用於截圖等需要監聽特定事件的功能。
     * 返回取消訂閱函數。
     *
     * @param callback 事件回調
     * @returns 取消訂閱函數
     */
    onEvent(callback: (event: VideoEvent) => void): () => void {
        if (!this.controller) {
            return () => {};
        }
        return this.controller.onEvent(callback);
    }

    checkFileSupport(filePath: string) {
        if (!this.controller) return { supported: false, hasVideo: false, hasAudio: false, error: 'No controller' };
        return this.controller.checkFileSupport(filePath);
    }

    // ===== Scrubbing 模式 =====

    private _scrubbing = false;

    setScrubbing(enabled: boolean): void {
        this._scrubbing = enabled;
        // Native 模式下，scrubbing 主要用於 RenderManager 決定渲染行為
        // 不需要額外的 native 調用
    }

    isScrubbing(): boolean {
        return this._scrubbing;
    }

    // ===== 兼容 InstanceManager API（返回 Promise 版本）=====

    /**
     * 異步獲取單幀（兼容 InstanceManager 接口）
     * 直連模式下，這等同於 renderFrame
     */
    async getFrame(): Promise<FrameData | null> {
        return this.renderFrame();
    }

    /**
     * 異步獲取 HDR 信息
     */
    async getHdrInfoAsync(): Promise<{
        isHdr: boolean;
        primaries: string;
        transfer: string;
        maxLuminance: number;
        hdrModeEnabled: boolean;
    } | null> {
        return this.getHdrInfo();
    }

    /**
     * 異步設置 HDR 模式
     */
    async setHdrModeAsync(enabled: boolean): Promise<boolean> {
        return this.setHdrMode(enabled);
    }

    /**
     * 異步載入視頻
     */
    async loadAsync(src: string): Promise<boolean> {
        return this.load(src);
    }

    /**
     * 異步播放
     */
    async playAsync(): Promise<boolean> {
        return this.play();
    }

    /**
     * 異步暫停
     */
    async pauseAsync(): Promise<boolean> {
        return this.pause();
    }

    /**
     * 異步 seek
     */
    async seekAsync(position: number, mode: 'absolute' | 'relative' = 'absolute'): Promise<void> {
        this.seek(position, mode);
    }

    /**
     * 異步獲取狀態
     */
    async getStateAsync(): Promise<VideoState | null> {
        return this.getState();
    }

    /**
     * 異步獲取元數據
     */
    async getMetadataAsync(): Promise<{
        fps: number;
        width: number;
        height: number;
        isHdr: boolean;
        hdrPrimaries: string;
        hdrTransfer: string;
        hdrMaxLuminance: number;
        videoCodec?: string;
        audioCodec?: string;
        format?: string;
        bitrate?: number;
        rotation?: number;
        sampleRate?: number;
        channels?: number;
    } | null> {
        const meta = this.getMetadata();
        if (!meta) return null;
        return {
            fps: meta.fps,
            width: meta.width,
            height: meta.height,
            isHdr: meta.isHdr,
            hdrPrimaries: meta.hdrPrimaries,
            hdrTransfer: meta.hdrTransfer,
            hdrMaxLuminance: meta.hdrMaxLuminance,
            videoCodec: meta.videoCodec,
            audioCodec: meta.audioCodec,
            format: meta.format,
            bitrate: meta.bitrate,
            rotation: meta.rotation,
            sampleRate: meta.sampleRate,
            channels: meta.channels,
        };
    }

    // ===== 幀推送控制（兼容 API，直連模式不使用）=====

    async startFramePush(_targetResolution?: { width: number; height: number }): Promise<boolean> {
        // 直連模式不使用幀推送，總是返回成功
        return true;
    }

    async stopFramePush(): Promise<void> {
        // 直連模式不使用幀推送，無操作
    }

    async updateFramePushResolution(_resolution: { width: number; height: number }): Promise<void> {
        // 直連模式不使用幀推送，無操作
    }
}

/**
 * 生成唯一實例 ID
 */
export function generateInstanceId(): string {
    return `mpv-native-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
}
