/**
 * RenderManager - 視頻渲染管理
 *
 * 直連模式：rAF 循環直接呼叫 renderFrame() 並渲染
 *
 * Queue 的作用（在 scrubbing 時）：
 * - seek 時立即獲取幀並推送到 Queue
 * - rAF 從 Queue 消費（最多 3 幀追趕）
 * - 這樣快速拖拽時不會丟失中間幀
 */

import type { WebGLVideoRenderer } from '../../video-player/webgl-renderer';
import type { AdaptiveFpsController } from '../AdaptiveFpsController';
import type { InstanceManager } from './InstanceManager';

/**
 * 幀數據
 */
export interface FrameData {
    buffer: ArrayBuffer;
    width: number;
    height: number;
    rotation: number;
    format: 'rgba' | 'yuv420';
}

/**
 * 渲染管理器配置
 */
export interface RenderManagerConfig {
    /** WebGL 渲染器 */
    renderer: WebGLVideoRenderer;
    /** 自適應幀率控制器 */
    fpsController: AdaptiveFpsController;
    /** Native 實例管理器 */
    instanceManager: InstanceManager;
    /** 獲取元素尺寸的回調 */
    getElementSize: () => { width: number; height: number } | null;
    /** 視頻尺寸變化回調 */
    onVideoSizeChange?: (width: number, height: number) => void;
    /** stalled 回調 */
    onStalled?: () => void;
    /** 獲取播放狀態 */
    getPlaybackState: () => { paused: boolean; seeking: boolean; scrubbing: boolean };
    /** 檢查元素是否連接到 DOM */
    isConnected?: () => boolean;
}

/**
 * RenderManager - 直連模式渲染管理器
 */
export class RenderManager {
    private config: RenderManagerConfig;

    // 渲染狀態
    private animationFrameId: number | null = null;
    private renderActive = false;
    private lastTargetResolution = '';

    // Frame Queue（用於 scrubbing 時緩衝）
    private frameQueue: FrameData[] = [];
    private static readonly MAX_FRAME_QUEUE_SIZE = 8;

    // Scrubbing 優化：使用較低解析度加速解碼
    private static readonly SCRUBBING_MAX_WIDTH = 1280;
    private static readonly SCRUBBING_MAX_HEIGHT = 720;

    // 當前視頻尺寸
    private videoWidth = 0;
    private videoHeight = 0;

    // 當前格式
    private currentFormat: 'rgba' | 'yuv420' = 'yuv420';

    // 渲染統計
    private lastFrameTime = 0;
    private lastRenderTime = 0;
    private lastResolutionCheckTime = 0;

    // 常量
    private static readonly PAUSED_INTERVAL = 100;
    private static readonly STALLED_THRESHOLD = 3000;
    private static readonly RESOLUTION_CHECK_INTERVAL = 500;

    // 用於取消渲染循環
    private currentLoadId = 0;

    // 目標分辨率防抖（避免 resize 時頻繁觸發 vf 更新）
    private targetResolutionDebounceTimer: ReturnType<typeof setTimeout> | null = null;
    private pendingTargetResolution: { width: number; height: number } | null = null;
    private static readonly TARGET_RESOLUTION_DEBOUNCE_MS = 150;

    constructor(config: RenderManagerConfig) {
        this.config = config;
    }

    /**
     * 更新配置
     */
    updateConfig(config: Partial<RenderManagerConfig>): void {
        this.config = { ...this.config, ...config };
    }

    /**
     * 計算目標解析度
     */
    private getTargetResolution(): { width: number; height: number } | undefined {
        const size = this.config.getElementSize();
        if (!size || size.width <= 0 || size.height <= 0) {
            return undefined;
        }

        const dpr = window.devicePixelRatio || 1;
        const result = {
            width: Math.ceil(size.width * dpr),
            height: Math.ceil(size.height * dpr),
        };

        return result;
    }

    /**
     * 設置目標分辨率（帶防抖）
     * @param width 目標寬度
     * @param height 目標高度
     * @param immediate 是否立即執行（跳過防抖）
     */
    private setTargetResolutionDebounced(
        width: number,
        height: number,
        immediate = false
    ): void {
        const newTarget = `${width}x${height}`;
        if (newTarget === this.lastTargetResolution) {
            return; // 無變化
        }

        // 立即更新 lastTargetResolution，避免防抖期間重複觸發
        this.lastTargetResolution = newTarget;

        // 保存待處理的值
        this.pendingTargetResolution = { width, height };

        if (immediate) {
            // 立即執行（用於初始化）
            this.applyPendingTargetResolution();
            return;
        }

        // 防抖：清除舊的 timer，設置新的
        if (this.targetResolutionDebounceTimer) {
            clearTimeout(this.targetResolutionDebounceTimer);
        }
        this.targetResolutionDebounceTimer = setTimeout(() => {
            this.applyPendingTargetResolution();
        }, RenderManager.TARGET_RESOLUTION_DEBOUNCE_MS);
    }

    /**
     * 應用待處理的目標分辨率
     */
    private applyPendingTargetResolution(): void {
        if (!this.pendingTargetResolution) {
            return;
        }

        const { width, height } = this.pendingTargetResolution;
        this.config.instanceManager.setTargetResolution(width, height);
        this.pendingTargetResolution = null;
        this.targetResolutionDebounceTimer = null;
    }

    /**
     * 啟動渲染循環
     */
    async startRenderLoop(): Promise<void> {
        if (this.animationFrameId !== null) return;

        const loadId = ++this.currentLoadId;
        const targetResolution = this.getTargetResolution();

        this.renderActive = true;
        this.frameQueue.length = 0;

        if (targetResolution) {
            // 初始化時立即設置目標分辨率（跳過防抖），確保第一幀就使用 vf scale
            this.setTargetResolutionDebounced(
                targetResolution.width,
                targetResolution.height,
                true // immediate
            );
            console.log(`[RenderManager] Starting, target: ${this.lastTargetResolution}`);
        } else {
            console.log('[RenderManager] Starting');
        }

        this.lastRenderTime = 0;
        this.lastResolutionCheckTime = 0;

        const renderLoop = (timestamp: number): void => {
            const isConnected = this.config.isConnected?.() ?? true;
            if (!this.renderActive || loadId !== this.currentLoadId || !isConnected) return;

            this.animationFrameId = requestAnimationFrame(renderLoop);
            this.renderFrame(timestamp);
        };

        this.animationFrameId = requestAnimationFrame(renderLoop);
    }

    /**
     * 渲染單幀
     */
    private renderFrame(timestamp: number): void {
        const state = this.config.getPlaybackState();
        const frameInterval = this.config.fpsController.getEffectiveFrameInterval();
        const timeSinceLastRender = timestamp - this.lastRenderTime;

        // === 目標分辨率更新（必須在 shouldRender 檢查之前！）===
        // 這樣即使不渲染新幀，也會更新 vf 濾鏡
        let targetResolution = this.getTargetResolution();

        // Scrubbing 優化：使用較低解析度
        if (state.scrubbing && targetResolution) {
            targetResolution = {
                width: Math.min(targetResolution.width, RenderManager.SCRUBBING_MAX_WIDTH),
                height: Math.min(targetResolution.height, RenderManager.SCRUBBING_MAX_HEIGHT),
            };
        }

        // 更新目標分辨率（透過 vf scale 濾鏡優化性能）
        // 使用防抖避免 resize 時頻繁觸發 vf 更新
        if (targetResolution) {
            // scrubbing 時立即響應（需要低分辨率快速預覽）
            // 正常播放時使用防抖
            this.setTargetResolutionDebounced(
                targetResolution.width,
                targetResolution.height,
                state.scrubbing // scrubbing 時 immediate
            );
        }

        // === 計算是否應該渲染 ===
        let shouldRender: boolean;
        if (state.seeking || state.scrubbing) {
            shouldRender = true;
        } else if (state.paused) {
            shouldRender = timeSinceLastRender >= RenderManager.PAUSED_INTERVAL;
        } else {
            shouldRender = timeSinceLastRender >= frameInterval;
        }

        if (!shouldRender) return;

        // Scrubbing 模式：優先從 Queue 消費（最多 3 幀追趕）
        if (state.scrubbing && this.frameQueue.length > 0) {
            const maxFrames = Math.min(3, this.frameQueue.length);
            for (let i = 0; i < maxFrames; i++) {
                const frame = this.frameQueue.shift()!;
                this.renderFrameToWebGL(frame, timestamp, state.paused, state.seeking);
            }
            return;
        }

        // renderFrame 不再傳遞 target 參數（由 setTargetResolution 處理）
        const frame = this.config.instanceManager.renderFrame();

        if (!frame) return;

        this.renderFrameToWebGL(frame, timestamp, state.paused, state.seeking);

        // 定期檢查 stalled 狀態
        if (timestamp - this.lastResolutionCheckTime >= RenderManager.RESOLUTION_CHECK_INTERVAL) {
            this.lastResolutionCheckTime = timestamp;
            this.checkStalled(timestamp, state.paused);
        }
    }

    /**
     * 渲染幀到 WebGL
     */
    private renderFrameToWebGL(
        frame: FrameData,
        timestamp: number,
        paused: boolean,
        seeking: boolean
    ): void {
        this.lastRenderTime = timestamp;

        // 記錄幀渲染完成時間
        if (!paused && !seeking) {
            this.config.fpsController.recordFrame(performance.now());
        }

        // 更新幀時間
        this.lastFrameTime = timestamp;

        // 檢查視頻尺寸變化
        if (this.videoWidth !== frame.width || this.videoHeight !== frame.height) {
            this.videoWidth = frame.width;
            this.videoHeight = frame.height;
            this.config.onVideoSizeChange?.(frame.width, frame.height);
        }

        // 更新格式
        this.currentFormat = frame.format;

        // 渲染到 WebGL
        this.config.renderer.updateFrameFromBuffer(
            frame.buffer,
            frame.width,
            frame.height,
            frame.rotation,
            frame.format
        );
    }

    /**
     * 檢查 stalled 狀態
     */
    private checkStalled(timestamp: number, paused: boolean): void {
        if (!paused &&
            this.lastFrameTime > 0 &&
            timestamp - this.lastFrameTime > RenderManager.STALLED_THRESHOLD) {
            this.config.onStalled?.();
        }
    }

    /**
     * 停止渲染循環
     */
    async stopRenderLoop(): Promise<void> {
        this.currentLoadId++;

        if (this.animationFrameId !== null) {
            cancelAnimationFrame(this.animationFrameId);
            this.animationFrameId = null;
        }

        // 清理防抖 timer
        if (this.targetResolutionDebounceTimer) {
            clearTimeout(this.targetResolutionDebounceTimer);
            this.targetResolutionDebounceTimer = null;
            this.pendingTargetResolution = null;
        }

        if (this.renderActive) {
            this.renderActive = false;
            this.frameQueue.length = 0;
            console.log('[RenderManager] Stopped');
        }
    }

    /**
     * 重置渲染狀態
     */
    reset(): void {
        this.currentLoadId++;
        this.videoWidth = 0;
        this.videoHeight = 0;
        this.lastFrameTime = 0;
        this.frameQueue.length = 0;
        this.lastTargetResolution = '';

        // 清理防抖 timer
        if (this.targetResolutionDebounceTimer) {
            clearTimeout(this.targetResolutionDebounceTimer);
            this.targetResolutionDebounceTimer = null;
            this.pendingTargetResolution = null;
        }
    }

    /**
     * 獲取當前視頻尺寸
     */
    getVideoSize(): { width: number; height: number } {
        return { width: this.videoWidth, height: this.videoHeight };
    }

    /**
     * 獲取當前格式
     */
    getCurrentFormat(): 'rgba' | 'yuv420' {
        return this.currentFormat;
    }

    /**
     * 是否正在渲染
     */
    isRendering(): boolean {
        return this.renderActive;
    }

    /**
     * 清除緩存
     */
    clearCache(): void {
        this.frameQueue.length = 0;
    }

    /**
     * 清空幀隊列
     */
    clearFrameQueue(): void {
        this.frameQueue.length = 0;
    }

    /**
     * 獲取幀隊列長度
     */
    getFrameQueueLength(): number {
        return this.frameQueue.length;
    }

    /**
     * Seek 後渲染幀（用於 scrubbing 時緩衝或暫停時預覽）
     *
     * - 渲染循環運行中：推送到 Queue（rAF 消費，最多 3 幀追趕）
     * - 渲染循環停止：直接渲染到 WebGL（暫停時 seek 預覽）
     *
     * @param useLowRes 是否使用低分辨率（scrubbing 用）
     * @param waitForFrame 是否等待幀就緒（精準 seek 結束時用）
     */
    pollFrameAfterSeek(useLowRes: boolean = false, waitForFrame: boolean = false): void {
        // 計算目標解析度
        let targetResolution = this.getTargetResolution();

        if (useLowRes && targetResolution) {
            targetResolution = {
                width: Math.min(targetResolution.width, RenderManager.SCRUBBING_MAX_WIDTH),
                height: Math.min(targetResolution.height, RenderManager.SCRUBBING_MAX_HEIGHT),
            };
        }

        // 更新目標分辨率（seek/scrubbing 時立即響應）
        if (targetResolution) {
            this.setTargetResolutionDebounced(
                targetResolution.width,
                targetResolution.height,
                true // seek 時 immediate
            );
        }

        // 獲取幀
        let frame = this.config.instanceManager.renderFrame();

        // 如果需要等待幀就緒（精準 seek 結束時），重試幾次
        if (!frame && waitForFrame) {
            let retries = 0;
            const maxRetries = 10;
            const retryInterval = 16; // ~1 frame at 60fps

            const tryGetFrame = () => {
                frame = this.config.instanceManager.renderFrame();
                if (frame && frame.width > 0 && frame.height > 0) {
                    this.renderFrameToWebGL(frame, performance.now(), true, true);
                } else if (retries < maxRetries) {
                    retries++;
                    setTimeout(tryGetFrame, retryInterval);
                }
            };

            setTimeout(tryGetFrame, retryInterval);
            return;
        }

        if (frame && frame.width > 0 && frame.height > 0) {
            if (this.renderActive) {
                // 渲染循環運行中：推送到 Queue（scrubbing 用）
                this.frameQueue.push({
                    buffer: frame.buffer,
                    width: frame.width,
                    height: frame.height,
                    rotation: frame.rotation,
                    format: frame.format,
                });

                // 限制 Queue 長度
                while (this.frameQueue.length > RenderManager.MAX_FRAME_QUEUE_SIZE) {
                    this.frameQueue.shift();
                }
            } else {
                // 渲染循環停止：直接渲染到 WebGL（暫停時 seek 預覽）
                this.renderFrameToWebGL(frame, performance.now(), true, true);
            }
        }
    }

    /**
     * 停止快速輪詢（兼容 API）
     */
    stopFastPoll(): void {
        // 不需要特殊處理
    }

    /**
     * 渲染單幀（用於初始化第一幀或暫停時預覽）
     * 不啟動渲染循環，直接渲染到 WebGL
     */
    renderSingleFrame(): boolean {
        const frame = this.config.instanceManager.renderFrame();
        if (!frame || frame.width <= 0 || frame.height <= 0) {
            return false;
        }
        this.renderFrameToWebGL(frame, performance.now(), true, false);
        return true;
    }
}
