/**
 * MediaFacade - HTMLMediaElement API 兼容層
 *
 * 提供與原生 <video> 標籤一致的 API 介面，
 * 內部使用 InstanceManager 進行播放控制。
 */

import type { InstanceManager } from './InstanceManager';
import type { RenderManager } from './RenderManager';
import type { VideoEventManager } from '../VideoEventManager';
import type { AdaptiveFpsController } from '../AdaptiveFpsController';
import type { MediaState } from '../../../core/StateStore';
import { NetworkState, ReadyState, MediaErrorImpl } from '../VideoEventManager';
// 預設幀率 - 當無法讀取視頻 FPS 時使用
const DEFAULT_FPS = 24;

/**
 * HDR 資訊
 */
export interface HdrInfo {
    isHdr: boolean;
    primaries: string;
    transfer: string;
    maxLuminance: number;
    hdrModeEnabled: boolean;
}

/**
 * 截圖選項
 */
export interface ScreenshotOptions {
    /** 最大寬度（保持比例縮放） */
    maxWidth?: number;
    /** 最大高度（保持比例縮放） */
    maxHeight?: number;
}

/**
 * 完整元數據
 */
export interface FullMetadata {
    duration: number;
    width: number;
    height: number;
    rotation: number;
    format: string;
    videoCodec: string;
    audioCodec: string;
    bitrate: number;
    fps: number;
    isHdr: boolean;
    hdrPrimaries: string;
    hdrTransfer: string;
    hdrMaxLuminance: number;
    sampleRate: number;
    channels: number;
}

/**
 * MediaFacade 配置
 */
export interface MediaFacadeConfig {
    /** 實例 ID */
    instanceId: string;
    instanceManager: InstanceManager;
    renderManager: RenderManager;
    eventManager: VideoEventManager;
    fpsController: AdaptiveFpsController;
    mediaState: MediaState;
    /** 檢查元素是否連接到 DOM */
    isConnected: () => boolean;
    /** 獲取 loop 屬性 */
    getLoop: () => boolean;
    /** 獲取 autoplay 屬性 */
    getAutoplay: () => boolean;
    /** 獲取 defaultMuted 屬性 */
    getDefaultMuted: () => boolean;
    /** 獲取 muted 狀態 */
    getMuted: () => boolean;
    /** 設置 muted 狀態 */
    setMuted: (value: boolean) => void;
    /** Canvas 元素 */
    canvas: HTMLCanvasElement;
    /** WebGL 渲染器 */
    renderer: { resetState: () => void };
}

/**
 * 視頻元數據
 */
export interface VideoMetadata {
    fps: number;
    width: number;
    height: number;
    isHdr: boolean;
    hdrPrimaries: string;
    hdrTransfer: string;
    hdrMaxLuminance: number;
    videoCodec?: string;
    audioCodec?: string;
    format?: string;
    bitrate?: number;
    rotation?: number;
    sampleRate?: number;
    channels?: number;
}

/**
 * MediaFacade - 直連模式封裝
 */
export class MediaFacade {
    private config: MediaFacadeConfig;

    // HTMLMediaElement 屬性
    private _currentTime: number = 0;
    private _duration: number = 0;
    private _paused: boolean = true;
    private _volume: number = 1;
    private _playbackRate: number = 1;
    private _defaultPlaybackRate: number = 1;
    private _readyState: number = ReadyState.HAVE_NOTHING;
    private _networkState: number = NetworkState.NETWORK_EMPTY;
    private _seeking: boolean = false;
    private _currentSrc: string = '';

    // 視頻尺寸
    private _videoWidth: number = 0;
    private _videoHeight: number = 0;
    private _sourceWidth: number = 0;
    private _sourceHeight: number = 0;

    // 視頻元數據
    private _fps: number = DEFAULT_FPS;
    private _videoCodec: string = '';
    private _audioCodec: string = '';
    private _containerFormat: string = '';
    private _bitrate: number = 0;
    private _rotation: number = 0;
    private _sampleRate: number = 0;
    private _channels: number = 0;

    // HDR 資訊
    private _isHdr: boolean = false;
    private _hdrPrimaries: string = '';
    private _hdrTransfer: string = '';
    private _hdrMaxLuminance: number = 0;

    // 內部狀態
    private _ended: boolean = false;
    private _lastSeekTime: number = 0;
    private _scrubbing: boolean = false;
    private lastVolume: number = 1;
    private syncInterval: number | null = null;
    private skipNextStateSync: boolean = false;
    private currentLoadId: number = 0;

    // 兩階段 Seek 系統（從 IPC 架構恢復）
    // 高幀率/高解析度視頻：先 keyframe 快速顯示，停頓 100ms 後補精準幀
    private _usingFastSeek: boolean = false;
    private _preciseSeekTarget: number | null = null;
    private _preciseSeekTimer: ReturnType<typeof setTimeout> | null = null;
    private static readonly PRECISE_SEEK_DELAY_MS = 100;

    constructor(config: MediaFacadeConfig) {
        this.config = config;
    }

    // ===== HTMLMediaElement 屬性 Getters =====

    get currentTime(): number { return this._currentTime; }
    get duration(): number { return this._duration; }
    get paused(): boolean { return this._paused; }
    get volume(): number { return this._volume; }
    get playbackRate(): number { return this._playbackRate; }
    get defaultPlaybackRate(): number { return this._defaultPlaybackRate; }
    get readyState(): number { return this._readyState; }
    get networkState(): number { return this._networkState; }
    get seeking(): boolean { return this._seeking; }
    get currentSrc(): string { return this._currentSrc; }
    get videoWidth(): number { return this._videoWidth; }
    get videoHeight(): number { return this._videoHeight; }
    get sourceWidth(): number { return this._sourceWidth; }
    get sourceHeight(): number { return this._sourceHeight; }
    get fps(): number { return this._fps; }
    get videoCodec(): string { return this._videoCodec; }
    get audioCodec(): string { return this._audioCodec; }
    get containerFormat(): string { return this._containerFormat; }
    get bitrate(): number { return this._bitrate; }
    get rotation(): number { return this._rotation; }
    get sampleRate(): number { return this._sampleRate; }
    get channels(): number { return this._channels; }
    get isHdr(): boolean { return this._isHdr; }
    get hdrPrimaries(): string { return this._hdrPrimaries; }
    get hdrTransfer(): string { return this._hdrTransfer; }
    get hdrMaxLuminance(): number { return this._hdrMaxLuminance; }
    get scrubbing(): boolean { return this._scrubbing; }

    get ended(): boolean {
        return this._ended;
    }

    // ===== HTMLMediaElement 屬性 Setters =====

    set currentTime(value: number) {
        this._currentTime = value;
        this._lastSeekTime = Date.now();
        this.seekTo(value);
    }

    set volume(value: number) {
        const vol = Math.max(0, Math.min(1, value));
        const oldVol = this._volume;
        this._volume = vol;
        // 直連模式：直接調用 native
        this.config.instanceManager.setVolume(vol * 100);
        if (oldVol !== vol) {
            this.config.eventManager.updateVolume(vol, this.config.getMuted());
        }
    }

    set playbackRate(value: number) {
        const oldRate = this._playbackRate;
        this._playbackRate = value;
        // 直連模式：直接調用 native
        this.config.instanceManager.setSpeed(value);
        if (oldRate !== value) {
            this.config.eventManager.updatePlaybackRate(value);
        }
    }

    set defaultPlaybackRate(value: number) {
        this._defaultPlaybackRate = value;
    }

    // ===== 播放控制方法 =====

    async play(): Promise<void> {
        try {
            // 如果視頻已結束，先 seek 到開頭
            if (this._ended) {
                this._ended = false;
                this.seekTo(0);
            }

            // 直連模式：直接調用 native（同步）
            const success = this.config.instanceManager.play();
            if (success) {
                this._paused = false;
                this.skipNextStateSync = true;
                // 只有連接 DOM 時才啟動渲染循環和狀態同步
                if (this.config.isConnected()) {
                    this.config.renderManager.startRenderLoop();
                    this.startStateSync();
                }
                this.config.eventManager.play();
                this.config.fpsController.resumeCollection();
            }
        } catch (error) {
            console.error('[MediaFacade] Play error:', error);
            this.config.eventManager.emitError(MediaErrorImpl.MEDIA_ERR_ABORTED, 'Play failed');
            throw error;
        }
    }

    pause(): void {
        // 立即設置狀態
        this._paused = true;

        // 直連模式：直接調用 native（同步）
        const success = this.config.instanceManager.pause();
        if (success) {
            this.skipNextStateSync = true;
            this.config.eventManager.pause();
            this.config.fpsController.pauseCollection();
            // 注意：暫停時不停止渲染循環，否則 seek 時無法正確更新預覽
            // 渲染循環在暫停時會自動降低 polling 頻率（PAUSED_INTERVAL = 100ms）
            // 暫停時停止狀態同步，減少 GC 壓力
            // play() 時會重新啟動
            this.stopStateSync();
        }
    }

    toggle(): void {
        if (this._paused) {
            this.play();
        } else {
            this.pause();
        }
    }

    /**
     * 前進 n 幀
     */
    nextFrame(n: number = 1): void {
        const frameDuration = 1 / this._fps;
        const targetTime = Math.min(this._currentTime + n * frameDuration, this._duration);
        this.currentTime = targetTime;
    }

    /**
     * 後退 n 幀
     */
    prevFrame(n: number = 1): void {
        const frameDuration = 1 / this._fps;
        const targetTime = Math.max(this._currentTime - n * frameDuration, 0);
        this.currentTime = targetTime;
    }

    // 解碼壓力閾值：FPS × 面積 > 此值時使用 fast seek
    // 100M ≈ 1080p 50fps，超過此壓力就需要 fast seek
    private static readonly DECODE_PRESSURE_THRESHOLD = 100_000_000;

    /**
     * 計算解碼壓力，決定是否需要 fast seek
     *
     * 公式：FPS × 面積（width × height）
     * - 720p 60fps = 55M → 不需要
     * - 1080p 30fps = 62M → 不需要
     * - 1080p 60fps = 124M → 需要
     * - 4K 30fps = 248M → 需要
     */
    private needsFastSeek(): boolean {
        const fps = this._fps;
        const width = this._sourceWidth || this._videoWidth;
        const height = this._sourceHeight || this._videoHeight;

        // 如果 metadata 還沒讀取到，保守起見使用 fast seek
        if (width === 0 || height === 0 || fps <= 0) {
            console.log('[MediaFacade] needsFastSeek: metadata not ready, defaulting to fast seek');
            return true;
        }

        const decodePressure = fps * width * height;
        const needsFast = decodePressure > MediaFacade.DECODE_PRESSURE_THRESHOLD;

        console.log(`[MediaFacade] needsFastSeek: ${needsFast} (${width}x${height}@${fps}fps = ${Math.round(decodePressure / 1_000_000)}M, threshold=${Math.round(MediaFacade.DECODE_PRESSURE_THRESHOLD / 1_000_000)}M)`);
        return needsFast;
    }

    /**
     * 設置 scrubbing 模式（兩階段 Seek 系統）
     *
     * 根據解碼壓力決定 seek 模式：
     * - 低壓力（FPS × 面積 <= 100M）：精準 seek
     * - 高壓力（FPS × 面積 > 100M）：fast seek + 停頓後補精準幀
     */
    setScrubbing(enabled: boolean): void {
        const wasScrubbing = this._scrubbing;
        this._scrubbing = enabled;
        this.config.instanceManager.setScrubbing(enabled);

        if (enabled && !wasScrubbing) {
            // 進入 scrubbing 模式 - 根據解碼壓力決定
            const useFastSeek = this.needsFastSeek();
            if (useFastSeek) {
                this._usingFastSeek = true;
                this.config.instanceManager.setFastSeek(true);  // hr-seek=no
            } else {
                this._usingFastSeek = false;
            }
            // 確保渲染循環運行（load() 後可能未啟動）
            if (this.config.isConnected()) {
                this.config.renderManager.startRenderLoop();
            }
        } else if (!enabled && wasScrubbing) {
            // 離開 scrubbing 模式
            // 清理精準 seek 計時器
            if (this._preciseSeekTimer) {
                clearTimeout(this._preciseSeekTimer);
                this._preciseSeekTimer = null;
            }

            // 只有啟用了 fast seek 的視頻才需要恢復精準模式
            if (this._usingFastSeek) {
                // 如果有待執行的精準 seek，立即執行
                if (this._preciseSeekTarget !== null) {
                    const target = this._preciseSeekTarget;
                    this._preciseSeekTarget = null;

                    // 恢復精準 seek 模式
                    this.config.instanceManager.setFastSeek(false);

                    // 執行最終的精準 seek
                    this.config.instanceManager.seek(target, 'absolute');

                    // 更新預覽畫面，確保顯示的幀與實際位置一致
                    // waitForFrame=true 等待 mpv 解碼完成
                    this.config.renderManager.pollFrameAfterSeek(false, true);
                } else {
                    // 確保恢復精準 seek 模式
                    this.config.instanceManager.setFastSeek(false);
                }

                this._usingFastSeek = false;
            }
        }
    }

    /**
     * 載入視頻
     */
    async load(src: string, lifecycleSignal?: AbortSignal): Promise<boolean> {
        if (!src) {
            this._networkState = NetworkState.NETWORK_EMPTY;
            this._currentSrc = '';
            return false;
        }

        const loadId = ++this.currentLoadId;

        const isCancelled = (): boolean => {
            return loadId !== this.currentLoadId || lifecycleSignal?.aborted === true;
        };

        try {
            // 如果正在載入，先中止
            if (this._networkState === NetworkState.NETWORK_LOADING) {
                this.config.eventManager.abortLoad();
            }

            // 重置所有狀態
            this.config.renderManager.stopRenderLoop();
            this.stopStateSync();
            this.resetState();

            // 開始載入序列
            this.config.eventManager.startLoad();
            this.config.eventManager.updateProgress(0, 100);

            // 在 load 之前先設置 target resolution，讓 vf 濾鏡在第一幀就生效
            this.setInitialTargetResolution();

            // 直連模式：直接調用 native（同步）
            const success = this.config.instanceManager.load(src);

            if (isCancelled()) return false;

            if (success) {
                this.config.eventManager.updateProgress(50, 100);

                // 等待第一幀
                let retries = 0;
                let frameData = this.config.instanceManager.renderFrame();

                while (!frameData && retries < 50) {
                    if (isCancelled()) return false;
                    await new Promise(r => setTimeout(r, 50));
                    frameData = this.config.instanceManager.renderFrame();
                    retries++;
                    this.config.eventManager.updateProgress(50 + retries, 100);
                }

                if (isCancelled()) return false;

                if (frameData) {
                    this._videoWidth = frameData.width;
                    this._videoHeight = frameData.height;
                }

                // 獲取 state 和 metadata（直連模式是同步的）
                const state = this.config.instanceManager.getState();

                if (isCancelled()) return false;

                if (state) {
                    this._duration = state.duration;
                    this._volume = state.volume / 100;

                    // 加載後默認暫停
                    if (!state.paused) {
                        this.config.instanceManager.pause();
                    }
                    this._paused = true;
                }

                // 等待 mpv 完成 metadata 解析
                // 第一次載入時，第一幀出來後 mpv 可能還沒完成 metadata 解析
                // 等待一個固定時間讓 mpv 完成解析
                await new Promise(r => setTimeout(r, 150));

                if (isCancelled()) return false;

                const metadata = this.config.instanceManager.getMetadata();
                if (metadata) {
                    this.applyMetadata(metadata);
                }

                if (isCancelled()) return false;

                // 觸發事件序列
                this._readyState = ReadyState.HAVE_METADATA;
                this.config.eventManager.loadedMetadata(this._duration, this._videoWidth, this._videoHeight);

                this._readyState = ReadyState.HAVE_CURRENT_DATA;
                this.config.eventManager.loadedData();

                this._readyState = ReadyState.HAVE_FUTURE_DATA;
                this.config.eventManager.canPlay();

                this._readyState = ReadyState.HAVE_ENOUGH_DATA;
                this._networkState = NetworkState.NETWORK_IDLE;
                this._currentSrc = src;
                this.config.canvas.classList.remove('no-video');
                this.config.eventManager.canPlayThrough();

                // 應用靜音狀態（如果 muted 屬性存在）
                if (this.config.getMuted()) {
                    this.setMuted(true);
                    // 觸發 volumechange 事件以更新 UI
                    this.config.eventManager.updateVolume(0, true);
                }
                if (this._defaultPlaybackRate !== 1) {
                    this.playbackRate = this._defaultPlaybackRate;
                }

                // 確保 seek 模式重置為精準模式（視頻載入後才有效）
                this.config.instanceManager.setFastSeek(false);

                // 啟動狀態同步
                this.startStateSync();

                // 只有連接 DOM 時才渲染第一幀（不啟動渲染循環，節省 GPU）
                if (this.config.isConnected()) {
                    this.config.renderManager.renderSingleFrame();
                }

                // autoplay - play() 會啟動渲染循環
                if (this.config.getAutoplay() && this._paused) {
                    this.play();
                }

                return true;
            } else {
                this._networkState = NetworkState.NETWORK_NO_SOURCE;
                this._readyState = ReadyState.HAVE_NOTHING;
                this.config.eventManager.emitError(
                    MediaErrorImpl.MEDIA_ERR_SRC_NOT_SUPPORTED,
                    'Failed to load video: format not supported or file not found'
                );
                return false;
            }
        } catch (error) {
            if (isCancelled()) return false;

            console.error('[MediaFacade] Load error:', error);
            this._networkState = NetworkState.NETWORK_NO_SOURCE;
            this._readyState = ReadyState.HAVE_NOTHING;
            this.config.eventManager.emitError(
                MediaErrorImpl.MEDIA_ERR_NETWORK,
                error instanceof Error ? error.message : 'Unknown error'
            );
            return false;
        }
    }

    /**
     * 中止載入
     */
    abort(): void {
        if (this._networkState === NetworkState.NETWORK_LOADING) {
            this.currentLoadId++;
            this._networkState = NetworkState.NETWORK_IDLE;
            this.config.eventManager.abortLoad();
        }
    }

    // ===== 內部方法 =====

    private seekTo(position: number): void {
        this._ended = false;
        this._seeking = true;
        this.config.eventManager.startSeek();
        this.config.fpsController.pauseCollection();

        try {
            // 兩階段 Seek 系統：scrubbing 模式下使用快速 seek，停頓後補精準幀
            if (this._scrubbing && this._usingFastSeek) {
                // 記錄目標位置（用於停頓後精準 seek）
                this._preciseSeekTarget = position;

                // 清除舊的精準 seek 計時器
                if (this._preciseSeekTimer) {
                    clearTimeout(this._preciseSeekTimer);
                }

                // 設置新的精準 seek 計時器（100ms 後執行）
                this._preciseSeekTimer = setTimeout(() => {
                    this.executePreciseSeek();
                }, MediaFacade.PRECISE_SEEK_DELAY_MS);

                // 立即執行快速 seek（keyframe only）
                this.config.instanceManager.seek(position, 'absolute');

                // 關鍵優化：快速輪詢取幀，不等待 rAF（從舊 IPC 架構恢復）
                // 這讓 seek 響應時間從 ~16ms 降低到 ~8ms 以內
                this.config.renderManager.pollFrameAfterSeek(true);  // useLowRes = true
            } else if (this._scrubbing) {
                // Scrubbing 但不需要快速 seek（低解析度/低幀率視頻）
                this.config.instanceManager.seek(position, 'absolute');
                this.config.renderManager.pollFrameAfterSeek(true);  // useLowRes = true
            } else {
                // 非 scrubbing 模式：直接精準 seek
                this.config.instanceManager.seek(position, 'absolute');

                // 暫停時也使用快速輪詢以立即更新畫面
                if (this._paused) {
                    this.config.renderManager.pollFrameAfterSeek(false);  // useLowRes = false
                }
            }

            this._seeking = false;
            this.config.eventManager.endSeek(position);
            if (!this._paused) {
                this.config.fpsController.resumeCollection();
            }
        } catch (error) {
            this._seeking = false;
            console.error('[MediaFacade] Seek error:', error);
            this.config.eventManager.endSeek(this._currentTime);
            if (!this._paused) {
                this.config.fpsController.resumeCollection();
            }
        }
    }

    /**
     * 執行精準 seek（兩階段系統的第二階段）
     *
     * 當用戶停頓拖拽 100ms 後，臨時切換到精準模式，
     * seek 到目標位置，然後恢復快速 seek 模式。
     */
    private executePreciseSeek(): void {
        if (this._preciseSeekTarget === null) return;

        const target = this._preciseSeekTarget;
        this._preciseSeekTarget = null;
        this._preciseSeekTimer = null;

        // 臨時切換到精準 seek 模式
        this.config.instanceManager.setFastSeek(false);

        // 執行精準 seek
        this.config.instanceManager.seek(target, 'absolute');

        // 取精準幀，waitForFrame=true 等待 mpv 解碼完成
        // 使用低解析度因為仍在 scrubbing 模式
        this.config.renderManager.pollFrameAfterSeek(this._scrubbing, true);

        // 恢復快速 seek 模式（如果仍在 scrubbing）
        if (this._scrubbing && this._usingFastSeek) {
            this.config.instanceManager.setFastSeek(true);
        }
    }

    private resetState(): void {
        this._currentTime = 0;
        this._duration = 0;
        this._paused = true;
        this._ended = false;
        this._readyState = ReadyState.HAVE_NOTHING;
        this._networkState = NetworkState.NETWORK_LOADING;
        this._videoWidth = 0;
        this._videoHeight = 0;
        this._sourceWidth = 0;
        this._sourceHeight = 0;
        this._videoCodec = '';
        this._audioCodec = '';
        this._containerFormat = '';
        this._bitrate = 0;
        this._rotation = 0;
        this._sampleRate = 0;
        this._channels = 0;
        this._seeking = false;
        this._currentSrc = '';
        this._fps = DEFAULT_FPS;
        this._isHdr = false;
        this._hdrPrimaries = '';
        this._hdrTransfer = '';
        this._hdrMaxLuminance = 0;
        this.skipNextStateSync = false;

        // 重置兩階段 Seek 狀態（重要：切換視頻時必須重置）
        this._scrubbing = false;
        this._usingFastSeek = false;
        this._preciseSeekTarget = null;
        if (this._preciseSeekTimer) {
            clearTimeout(this._preciseSeekTimer);
            this._preciseSeekTimer = null;
        }
        // 注意：不在這裡呼叫 setFastSeek(false)，因為第一次載入時視頻還沒載入
        // 正確的做法是在 NativeController 初始化時設置，以及在 load() 完成後重置
        this.config.instanceManager.setScrubbing(false);

        this.config.canvas.classList.add('no-video');
        this.config.renderer.resetState();
        this.config.fpsController.reset();
        this.config.renderManager.reset();
    }

    /**
     * 設置初始 target resolution（在 load 之前調用）
     * 讓 vf 濾鏡在第一幀就使用正確的目標尺寸
     */
    private setInitialTargetResolution(): void {
        const canvas = this.config.canvas;
        const rect = canvas.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
            const dpr = window.devicePixelRatio || 1;
            const targetWidth = Math.ceil(rect.width * dpr);
            const targetHeight = Math.ceil(rect.height * dpr);
            this.config.instanceManager.setTargetResolution(targetWidth, targetHeight);
        }
    }

    private applyMetadata(metadata: VideoMetadata | ReturnType<InstanceManager['getMetadata']>): void {
        if (!metadata) return;

        if (metadata.width > 0 && metadata.height > 0) {
            this._sourceWidth = metadata.width;
            this._sourceHeight = metadata.height;
        }
        if (metadata.fps > 0) {
            this._fps = metadata.fps;
            this.config.fpsController.setNativeFps(metadata.fps);
        }
        this._isHdr = metadata.isHdr;
        this._hdrPrimaries = metadata.hdrPrimaries;
        this._hdrTransfer = metadata.hdrTransfer;
        this._hdrMaxLuminance = metadata.hdrMaxLuminance;
        this._videoCodec = metadata.videoCodec || '';
        this._audioCodec = metadata.audioCodec || '';
        this._containerFormat = metadata.format || '';
        this._bitrate = metadata.bitrate || 0;
        this._rotation = metadata.rotation || 0;
        this._sampleRate = metadata.sampleRate || 0;
        this._channels = metadata.channels || 0;

        console.log(`[MediaFacade] Video metadata - ${this._sourceWidth}×${this._sourceHeight}, fps: ${this._fps}, codec: ${this._videoCodec}/${this._audioCodec}, bitrate: ${this._bitrate}, audio: ${this._sampleRate}Hz/${this._channels}ch, HDR: ${this._isHdr}${this._isHdr ? ` (${this._hdrTransfer}, ${this._hdrPrimaries})` : ''}`);
    }

    // ===== 狀態同步 =====

    startStateSync(): void {
        if (this.syncInterval !== null) return;

        const capturedLoadId = this.currentLoadId;

        this.syncInterval = window.setInterval(() => {
            if (!this.config.isConnected()) return;

            if (capturedLoadId !== this.currentLoadId) {
                this.stopStateSync();
                return;
            }

            try {
                // 直連模式：直接調用 native（同步）
                const state = this.config.instanceManager.getState();

                if (!this.config.isConnected()) return;
                if (capturedLoadId !== this.currentLoadId) return;

                if (state) {
                    const oldPaused = this._paused;
                    const oldDuration = this._duration;

                    const timeSinceLastSeek = Date.now() - this._lastSeekTime;
                    if (!this._seeking && timeSinceLastSeek > 300) {
                        this._currentTime = state.position;
                    }
                    this._paused = state.paused;

                    if (state.duration > 0 && state.duration !== this._duration) {
                        this._duration = state.duration;
                    }

                    this.config.eventManager.updateTime(this._currentTime);

                    if (oldDuration !== this._duration) {
                        this.config.eventManager.updateDuration(this._duration);
                    }

                    if (oldPaused !== this._paused && !this.skipNextStateSync) {
                        if (this._paused) {
                            this.config.eventManager.pause();
                        } else {
                            this.config.eventManager.play();
                        }
                    }
                    this.skipNextStateSync = false;

                    // 結尾偵測：keep-open=yes 下 mpv 不發 end-file，用 time threshold
                    if (!this._ended && this._duration > 0 &&
                        this._currentTime >= this._duration - 0.05) {
                        if (this.config.getLoop()) {
                            this.config.instanceManager.seek(0, 'absolute');
                            this.config.instanceManager.play();
                            this.skipNextStateSync = true;
                        } else {
                            this._ended = true;
                            this._paused = true;
                            this.config.instanceManager.pause();
                            this.config.eventManager.fireEnded();
                            this.stopStateSync();
                            return;
                        }
                    }

                    this.syncStateToSignals();
                }
            } catch (error) {
                if (capturedLoadId !== this.currentLoadId) return;
                console.error('[MediaFacade] State sync error:', error);
            }
        }, 100);
    }

    stopStateSync(): void {
        if (this.syncInterval !== null) {
            clearInterval(this.syncInterval);
            this.syncInterval = null;
        }
    }

    private syncStateToSignals(): void {
        const ms = this.config.mediaState;
        ms.currentTime.set(this._currentTime);
        ms.duration.set(this._duration);
        ms.paused.set(this._paused);
        ms.playing.set(!this._paused);
        ms.volume.set(this._volume);
        ms.muted.set(this._volume === 0);
        ms.playbackRate.set(this._playbackRate);
        ms.seeking.set(this._seeking);
        ms.videoWidth.set(this._videoWidth);
        ms.videoHeight.set(this._videoHeight);
        ms.src.set(this._currentSrc);
        ms.loop.set(this.config.getLoop());
        ms.isHdr.set(this._isHdr);
        ms.fps.set(this._fps);
        ms.ended.set(this.ended);
    }

    // ===== Muted 相關 =====

    setMuted(value: boolean): void {
        if (value) {
            this.lastVolume = this._volume;
            this.config.instanceManager.setVolume(0);
        } else {
            this.config.instanceManager.setVolume(this.lastVolume * 100);
        }
    }

    getLastVolume(): number {
        return this.lastVolume;
    }

    setLastVolume(value: number): void {
        this.lastVolume = value;
    }

    // ===== 視頻尺寸更新 =====

    updateVideoSize(width: number, height: number): void {
        this._videoWidth = width;
        this._videoHeight = height;
    }

    // ===== 當前載入 ID =====

    incrementLoadId(): void {
        this.currentLoadId++;
    }

    getCurrentLoadId(): number {
        return this.currentLoadId;
    }

    // ===== 獲取播放狀態 =====

    getPlaybackState(): { paused: boolean; seeking: boolean; scrubbing: boolean } {
        return {
            paused: this._paused,
            seeking: this._seeking,
            scrubbing: this._scrubbing,
        };
    }

    // ===== Metadata & HDR API =====

    /**
     * 獲取完整視頻元數據
     */
    async getMetadata(): Promise<FullMetadata | null> {
        const meta = this.config.instanceManager.getMetadata();
        if (!meta) return null;
        return {
            duration: this._duration,
            width: meta.width,
            height: meta.height,
            rotation: meta.rotation,
            format: meta.format,
            videoCodec: meta.videoCodec,
            audioCodec: meta.audioCodec,
            bitrate: meta.bitrate,
            fps: meta.fps,
            isHdr: meta.isHdr,
            hdrPrimaries: meta.hdrPrimaries,
            hdrTransfer: meta.hdrTransfer,
            hdrMaxLuminance: meta.hdrMaxLuminance,
            sampleRate: meta.sampleRate,
            channels: meta.channels,
        };
    }

    /**
     * 獲取 HDR 資訊
     */
    async getHdrInfo(): Promise<HdrInfo | null> {
        return this.config.instanceManager.getHdrInfo();
    }

    /**
     * 設置 HDR 模式
     */
    async setHdrMode(enabled: boolean): Promise<boolean> {
        return this.config.instanceManager.setHdrMode(enabled);
    }

    // ===== Screenshot API =====

    /** 截圖超時時間（毫秒） */
    private static readonly SCREENSHOT_TIMEOUT_MS = 5000;

    /** 截圖事件類型常數 */
    private static readonly SCREENSHOT_EVENT_TYPE = 'screenshot' as const;

    /** RGBA 像素位元組數 */
    private static readonly RGBA_BYTES_PER_PIXEL = 4;

    /** 當前進行中的截圖請求（用於序列化請求，避免競態條件） */
    private pendingScreenshot: Promise<ImageData | null> | null = null;

    /**
     * 擷取指定時間的視頻截圖
     *
     * @param time 時間點（秒，支援小數）
     * @param options 截圖選項
     * @returns ImageData 或 null（失敗時）
     *
     * @example
     * ```typescript
     * // 基本用法
     * const img = await video.screenshot(20.12);
     *
     * // 限制最大尺寸
     * const thumb = await video.screenshot(20.12, { maxWidth: 320, maxHeight: 240 });
     *
     * // 繪製到 Canvas
     * const canvas = document.createElement('canvas');
     * canvas.width = img.width;
     * canvas.height = img.height;
     * canvas.getContext('2d').putImageData(img, 0, 0);
     * ```
     */
    async screenshot(
        time: number,
        options?: ScreenshotOptions
    ): Promise<ImageData | null> {
        // 1. 輸入驗證
        if (!Number.isFinite(time) || time < 0) {
            console.warn('[MediaFacade] Invalid screenshot time:', time);
            return null;
        }

        if (options?.maxWidth !== undefined &&
            (!Number.isInteger(options.maxWidth) || options.maxWidth <= 0)) {
            console.warn('[MediaFacade] Invalid maxWidth:', options.maxWidth);
            return null;
        }

        if (options?.maxHeight !== undefined &&
            (!Number.isInteger(options.maxHeight) || options.maxHeight <= 0)) {
            console.warn('[MediaFacade] Invalid maxHeight:', options.maxHeight);
            return null;
        }

        // 2. 序列化請求：等待前一個請求完成，避免競態條件
        if (this.pendingScreenshot) {
            await this.pendingScreenshot;
        }

        // 3. 執行截圖
        this.pendingScreenshot = this.executeScreenshot(time, options);

        try {
            return await this.pendingScreenshot;
        } finally {
            this.pendingScreenshot = null;
        }
    }

    /**
     * 內部執行截圖邏輯
     */
    private executeScreenshot(
        time: number,
        options?: ScreenshotOptions
    ): Promise<ImageData | null> {
        return new Promise((resolve) => {
            let unsubscribe: (() => void) | null = null;
            let timeoutId: ReturnType<typeof setTimeout> | null = null;

            const cleanup = () => {
                if (unsubscribe) {
                    unsubscribe();
                    unsubscribe = null;
                }
                if (timeoutId) {
                    clearTimeout(timeoutId);
                    timeoutId = null;
                }
            };

            // 訂閱事件
            unsubscribe = this.config.instanceManager.onEvent((event) => {
                if (event.type === MediaFacade.SCREENSHOT_EVENT_TYPE) {
                    cleanup();

                    try {
                        const width = event.width as number;
                        const height = event.height as number;
                        const buffer = event.buffer as ArrayBuffer;

                        // RGBA buffer → ImageData（含大小驗證）
                        const imageData = this.bufferToImageData(buffer, width, height);

                        // 縮放（如果需要）
                        if (options?.maxWidth || options?.maxHeight) {
                            const scaled = this.scaleImageData(
                                imageData,
                                options.maxWidth,
                                options.maxHeight
                            );
                            resolve(scaled);
                        } else {
                            resolve(imageData);
                        }
                    } catch (error) {
                        console.error('[MediaFacade] Screenshot processing error:', error);
                        resolve(null);
                    }
                }
            });

            // 調用原生方法
            const success = this.config.instanceManager.requestScreenshot(time);
            if (!success) {
                cleanup();
                resolve(null);
                return;
            }

            // 超時保護
            timeoutId = setTimeout(() => {
                console.warn('[MediaFacade] Screenshot timeout');
                cleanup();
                resolve(null);
            }, MediaFacade.SCREENSHOT_TIMEOUT_MS);
        });
    }

    /**
     * 將 RGBA buffer 轉換為 ImageData
     * @throws 如果 buffer 大小不符合預期
     */
    private bufferToImageData(
        buffer: ArrayBuffer,
        width: number,
        height: number
    ): ImageData {
        const expectedSize = width * height * MediaFacade.RGBA_BYTES_PER_PIXEL;
        if (buffer.byteLength !== expectedSize) {
            throw new Error(
                `Buffer size mismatch: expected ${expectedSize}, got ${buffer.byteLength}`
            );
        }
        const data = new Uint8ClampedArray(buffer);
        return new ImageData(data, width, height);
    }

    /**
     * 縮放 ImageData
     */
    private scaleImageData(
        source: ImageData,
        maxWidth?: number,
        maxHeight?: number
    ): ImageData {
        const { width: targetWidth, height: targetHeight } = this.calculateTargetSize(
            source.width,
            source.height,
            maxWidth,
            maxHeight
        );

        // 無需縮放
        if (targetWidth === source.width && targetHeight === source.height) {
            return source;
        }

        // 使用 Canvas 縮放
        const srcCanvas = document.createElement('canvas');
        srcCanvas.width = source.width;
        srcCanvas.height = source.height;
        const srcCtx = srcCanvas.getContext('2d');
        if (!srcCtx) {
            throw new Error('Failed to get 2d context for source canvas');
        }
        srcCtx.putImageData(source, 0, 0);

        const dstCanvas = document.createElement('canvas');
        dstCanvas.width = targetWidth;
        dstCanvas.height = targetHeight;
        const dstCtx = dstCanvas.getContext('2d');
        if (!dstCtx) {
            throw new Error('Failed to get 2d context for destination canvas');
        }
        dstCtx.drawImage(srcCanvas, 0, 0, targetWidth, targetHeight);

        return dstCtx.getImageData(0, 0, targetWidth, targetHeight);
    }

    /**
     * 計算目標尺寸（保持比例）
     */
    private calculateTargetSize(
        srcWidth: number,
        srcHeight: number,
        maxWidth?: number,
        maxHeight?: number
    ): { width: number; height: number } {
        if (!maxWidth && !maxHeight) {
            return { width: srcWidth, height: srcHeight };
        }

        const aspectRatio = srcWidth / srcHeight;
        let width = srcWidth;
        let height = srcHeight;

        // 先處理寬度限制
        if (maxWidth && width > maxWidth) {
            width = maxWidth;
            height = Math.round(width / aspectRatio);
        }

        // 再處理高度限制
        if (maxHeight && height > maxHeight) {
            height = maxHeight;
            width = Math.round(height * aspectRatio);
        }

        return { width, height };
    }
}
