/**
 * MediaEventMixin - 動態生成 on* 事件處理器屬性
 *
 * 消除 MpvVideoElement 中 40+ 個手動定義的 on* getter/setter
 * 使用動態屬性定義，每個 on* 屬性都遵循相同模式
 */

import { VideoEventManager, MediaEventHandler } from '../VideoEventManager';

/**
 * 標準媒體事件列表
 * 符合 HTMLMediaElement 規範
 */
export const MEDIA_EVENTS = [
    // 載入相關事件
    'loadstart',
    'progress',
    'suspend',
    'abort',
    'error',
    'emptied',
    'stalled',

    // 元數據相關事件
    'loadedmetadata',
    'loadeddata',
    'durationchange',

    // 就緒相關事件
    'canplay',
    'canplaythrough',

    // 播放相關事件
    'play',
    'playing',
    'pause',
    'ended',
    'waiting',

    // 搜尋相關事件
    'seeking',
    'seeked',
    'timeupdate',

    // 參數相關事件
    'volumechange',
    'ratechange',

    // 尺寸相關事件
    'resize',
] as const;

export type MediaEventName = typeof MEDIA_EVENTS[number];

/**
 * 定義 on* 事件處理器屬性的接口
 * 用於 TypeScript 類型提示
 */
export interface MediaEventHandlers {
    onloadstart: MediaEventHandler;
    onprogress: MediaEventHandler;
    onsuspend: MediaEventHandler;
    onabort: MediaEventHandler;
    // onerror 在 HTMLElement 基類中有特殊處理
    onmediaerror: MediaEventHandler;
    onemptied: MediaEventHandler;
    onstalled: MediaEventHandler;
    onloadedmetadata: MediaEventHandler;
    onloadeddata: MediaEventHandler;
    ondurationchange: MediaEventHandler;
    oncanplay: MediaEventHandler;
    oncanplaythrough: MediaEventHandler;
    onplay: MediaEventHandler;
    onplaying: MediaEventHandler;
    onpause: MediaEventHandler;
    onended: MediaEventHandler;
    onwaiting: MediaEventHandler;
    onseeking: MediaEventHandler;
    onseeked: MediaEventHandler;
    ontimeupdate: MediaEventHandler;
    onvolumechange: MediaEventHandler;
    onratechange: MediaEventHandler;
    onresize: MediaEventHandler;
}

/**
 * 需要訪問 eventManager 的目標接口
 */
interface EventManagerHost {
    eventManager: VideoEventManager;
}

/**
 * 將 on* 事件處理器屬性混入到目標類
 *
 * 用法：
 * ```typescript
 * class MyElement extends HTMLElement {
 *     eventManager: VideoEventManager;
 *
 *     constructor() {
 *         super();
 *         this.eventManager = new VideoEventManager(this);
 *     }
 * }
 *
 * // 混入事件處理器
 * applyMediaEventHandlers(MyElement.prototype);
 * ```
 *
 * @param target - 目標原型（通常是 Class.prototype）
 */
export function applyMediaEventHandlers(target: object): void {
    for (const event of MEDIA_EVENTS) {
        // 特殊處理：error 事件使用 onmediaerror
        // 因為 onerror 在 HTMLElement 中有特殊含義
        const propName = event === 'error' ? 'onmediaerror' : `on${event}`;

        Object.defineProperty(target, propName, {
            get(this: EventManagerHost): MediaEventHandler {
                return this.eventManager.getEventHandler(event);
            },
            set(this: EventManagerHost, handler: MediaEventHandler): void {
                this.eventManager.setEventHandler(event, handler);
            },
            enumerable: true,
            configurable: true,
        });
    }
}

/**
 * 創建事件處理器的 Map
 * 用於直接在對象上定義而非原型
 *
 * @param eventManager - 事件管理器實例
 * @returns 屬性描述符對象
 */
export function createMediaEventDescriptors(
    eventManagerGetter: () => VideoEventManager
): PropertyDescriptorMap {
    const descriptors: PropertyDescriptorMap = {};

    for (const event of MEDIA_EVENTS) {
        const propName = event === 'error' ? 'onmediaerror' : `on${event}`;

        descriptors[propName] = {
            get(): MediaEventHandler {
                return eventManagerGetter().getEventHandler(event);
            },
            set(handler: MediaEventHandler): void {
                eventManagerGetter().setEventHandler(event, handler);
            },
            enumerable: true,
            configurable: true,
        };
    }

    return descriptors;
}
