/**
 * VideoEventManager - 管理 MpvVideoElement 的所有媒體事件
 *
 * 符合 W3C HTMLMediaElement 規範的事件系統
 * 參考: https://developer.mozilla.org/en-US/docs/Web/API/HTMLMediaElement
 *
 * 事件觸發順序（正常載入）:
 * loadstart → progress → suspend → loadedmetadata →
 * loadeddata → canplay → canplaythrough → play →
 * playing → timeupdate (重複) → pause/ended
 */

/** 媒體事件類型 - 符合 HTMLMediaElement 規範 */
export type MediaEventType =
    // 載入相關
    | 'loadstart'       // 開始載入資源
    | 'progress'        // 正在載入資源（定期觸發）
    | 'suspend'         // 載入被暫停
    | 'abort'           // 載入被中止（非錯誤）
    | 'error'           // 載入錯誤
    | 'emptied'         // 媒體已清空
    | 'stalled'         // 數據獲取停滯
    // 元數據相關
    | 'loadedmetadata'  // 元數據已載入
    | 'loadeddata'      // 第一幀已載入
    | 'durationchange'  // 時長已更新
    // 播放就緒相關
    | 'canplay'         // 可以開始播放
    | 'canplaythrough'  // 可以播放到結尾
    // 播放控制相關
    | 'play'            // paused 從 true 變為 false
    | 'playing'         // 播放已就緒並開始
    | 'pause'           // 已暫停
    | 'ended'           // 播放結束
    | 'waiting'         // 等待數據中
    // 播放位置相關
    | 'seeking'         // 搜尋開始
    | 'seeked'          // 搜尋完成
    | 'timeupdate'      // 時間已更新
    // 播放參數相關
    | 'volumechange'    // 音量已變更
    | 'ratechange'      // 播放速率已變更
    // 尺寸相關
    | 'resize';         // 視頻尺寸已變更

/** 內部狀態追蹤 */
interface MediaState {
    // 網絡狀態
    networkState: NetworkState;
    // 就緒狀態
    readyState: ReadyState;
    // 播放狀態
    paused: boolean;
    ended: boolean;
    seeking: boolean;
    // 媒體屬性
    currentTime: number;
    duration: number;
    volume: number;
    muted: boolean;
    playbackRate: number;
    // 視頻尺寸
    videoWidth: number;
    videoHeight: number;
    // 緩衝相關
    buffered: TimeRanges | null;
    // 載入進度
    loadProgress: number;
    // 錯誤
    error: MediaError | null;
}

/** 網絡狀態常量 */
export enum NetworkState {
    NETWORK_EMPTY = 0,      // 尚未初始化
    NETWORK_IDLE = 1,       // 資源已選擇但未使用網絡
    NETWORK_LOADING = 2,    // 正在下載數據
    NETWORK_NO_SOURCE = 3,  // 未找到資源
}

/** 就緒狀態常量 */
export enum ReadyState {
    HAVE_NOTHING = 0,       // 沒有可用資訊
    HAVE_METADATA = 1,      // 元數據可用
    HAVE_CURRENT_DATA = 2,  // 當前播放位置的數據可用
    HAVE_FUTURE_DATA = 3,   // 有足夠數據可播放到下一幀
    HAVE_ENOUGH_DATA = 4,   // 有足夠數據可播放到結尾
}

/** 事件處理器類型 */
export type MediaEventHandler = ((event: Event) => void) | null;

/** 時間範圍實現 */
export class TimeRangesImpl implements TimeRanges {
    private ranges: Array<{ start: number; end: number }>;

    constructor(ranges: Array<{ start: number; end: number }> = []) {
        this.ranges = ranges;
    }

    get length(): number {
        return this.ranges.length;
    }

    start(index: number): number {
        if (index < 0 || index >= this.ranges.length) {
            throw new DOMException('Index out of bounds', 'IndexSizeError');
        }
        return this.ranges[index].start;
    }

    end(index: number): number {
        if (index < 0 || index >= this.ranges.length) {
            throw new DOMException('Index out of bounds', 'IndexSizeError');
        }
        return this.ranges[index].end;
    }

    /** 添加時間範圍（內部使用） */
    addRange(start: number, end: number): void {
        // 使用二分查找找到插入位置，避免每次都 sort O(n log n)
        let left = 0;
        let right = this.ranges.length;
        while (left < right) {
            const mid = (left + right) >>> 1;
            if (this.ranges[mid].start < start) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        // 在正確位置插入
        this.ranges.splice(left, 0, { start, end });

        // 合併重疊範圍（單次遍歷 O(n)）
        const merged: Array<{ start: number; end: number }> = [];
        for (const range of this.ranges) {
            if (merged.length === 0 || merged[merged.length - 1].end < range.start) {
                merged.push(range);
            } else {
                merged[merged.length - 1].end = Math.max(merged[merged.length - 1].end, range.end);
            }
        }
        this.ranges = merged;
    }

    /** 清空所有範圍（內部使用） */
    clear(): void {
        this.ranges = [];
    }

    /** 設置完整緩衝（內部使用） */
    setFullyBuffered(duration: number): void {
        this.ranges = [{ start: 0, end: duration }];
    }
}

/** MediaError 實現 */
export class MediaErrorImpl implements MediaError {
    readonly code: number;
    readonly message: string;

    static readonly MEDIA_ERR_ABORTED = 1;
    static readonly MEDIA_ERR_NETWORK = 2;
    static readonly MEDIA_ERR_DECODE = 3;
    static readonly MEDIA_ERR_SRC_NOT_SUPPORTED = 4;

    readonly MEDIA_ERR_ABORTED = 1;
    readonly MEDIA_ERR_NETWORK = 2;
    readonly MEDIA_ERR_DECODE = 3;
    readonly MEDIA_ERR_SRC_NOT_SUPPORTED = 4;

    constructor(code: number, message: string = '') {
        this.code = code;
        this.message = message;
    }
}

/**
 * VideoEventManager - 事件管理器
 *
 * 負責追蹤媒體狀態並在適當時機觸發事件
 */
export class VideoEventManager {
    private element: EventTarget;
    private state: MediaState;
    private previousState: Partial<MediaState>;

    // on* 事件處理器
    private eventHandlers: Map<MediaEventType, MediaEventHandler> = new Map();

    // 防止重複觸發
    private firedEvents: Set<string> = new Set();
    private loadId: number = 0;

    constructor(element: EventTarget) {
        this.element = element;
        this.state = this.createInitialState();
        this.previousState = {};
    }

    /** 創建初始狀態 */
    private createInitialState(): MediaState {
        return {
            networkState: NetworkState.NETWORK_EMPTY,
            readyState: ReadyState.HAVE_NOTHING,
            paused: true,
            ended: false,
            seeking: false,
            currentTime: 0,
            duration: 0,
            volume: 1,
            muted: false,
            playbackRate: 1,
            videoWidth: 0,
            videoHeight: 0,
            buffered: new TimeRangesImpl(),
            loadProgress: 0,
            error: null,
        };
    }

    // ===== 狀態訪問器 =====

    get networkState(): NetworkState {
        return this.state.networkState;
    }

    get readyState(): ReadyState {
        return this.state.readyState;
    }

    get paused(): boolean {
        return this.state.paused;
    }

    get ended(): boolean {
        return this.state.ended;
    }

    get seeking(): boolean {
        return this.state.seeking;
    }

    get currentTime(): number {
        return this.state.currentTime;
    }

    get duration(): number {
        return this.state.duration;
    }

    get volume(): number {
        return this.state.volume;
    }

    get muted(): boolean {
        return this.state.muted;
    }

    get playbackRate(): number {
        return this.state.playbackRate;
    }

    get videoWidth(): number {
        return this.state.videoWidth;
    }

    get videoHeight(): number {
        return this.state.videoHeight;
    }

    get buffered(): TimeRanges {
        return this.state.buffered || new TimeRangesImpl();
    }

    get error(): MediaError | null {
        return this.state.error;
    }

    // ===== on* 事件處理器管理 =====

    setEventHandler(type: MediaEventType, handler: MediaEventHandler): void {
        this.eventHandlers.set(type, handler);
    }

    getEventHandler(type: MediaEventType): MediaEventHandler {
        return this.eventHandlers.get(type) || null;
    }

    // ===== 事件觸發 =====

    /** 觸發媒體事件 */
    emit(type: MediaEventType, eventInit?: EventInit): void {
        const event = new Event(type, { bubbles: false, cancelable: false, ...eventInit });

        // 調用 on* 處理器
        const handler = this.eventHandlers.get(type);
        if (handler) {
            handler.call(this.element, event);
        }

        // 派發到元素
        this.element.dispatchEvent(event);
    }

    /** 觸發錯誤事件 */
    emitError(code: number, message: string): void {
        this.state.error = new MediaErrorImpl(code, message);
        this.state.networkState = NetworkState.NETWORK_IDLE;
        this.state.readyState = ReadyState.HAVE_NOTHING;

        const event = new ErrorEvent('error', {
            message,
            bubbles: false,
            cancelable: false,
        });

        const handler = this.eventHandlers.get('error');
        if (handler) {
            handler.call(this.element, event);
        }

        this.element.dispatchEvent(event);
    }

    // ===== 載入流程事件 =====

    /** 開始載入新資源 - 觸發完整載入序列 */
    startLoad(): void {
        // 增加載入 ID，使之前的載入事件無效
        this.loadId++;
        this.firedEvents.clear();

        // 重置狀態
        this.state = this.createInitialState();
        this.state.networkState = NetworkState.NETWORK_LOADING;

        // 觸發 emptied（如果之前有內容）
        this.emit('emptied');

        // 觸發 loadstart
        this.emit('loadstart');
    }

    /** 中止載入 - abort 事件 */
    abortLoad(): void {
        if (this.state.networkState === NetworkState.NETWORK_LOADING) {
            this.state.networkState = NetworkState.NETWORK_IDLE;
            this.state.error = new MediaErrorImpl(MediaErrorImpl.MEDIA_ERR_ABORTED, 'Load aborted');
            this.emit('abort');
        }
    }

    /** 更新載入進度 - progress 事件 */
    updateProgress(loaded: number, total: number): void {
        const currentLoadId = this.loadId;

        if (this.state.networkState !== NetworkState.NETWORK_LOADING) return;

        this.state.loadProgress = total > 0 ? loaded / total : 0;

        // 更新 buffered 範圍
        if (this.state.duration > 0 && this.state.buffered instanceof TimeRangesImpl) {
            this.state.buffered.setFullyBuffered(this.state.duration * this.state.loadProgress);
        }

        // 只在同一次載入中觸發
        if (currentLoadId === this.loadId) {
            this.emit('progress');
        }
    }

    /** 載入暫停 - suspend 事件 */
    suspendLoad(): void {
        if (this.state.networkState === NetworkState.NETWORK_LOADING) {
            this.state.networkState = NetworkState.NETWORK_IDLE;
            this.emit('suspend');
        }
    }

    /** 數據停滯 - stalled 事件 */
    stalled(): void {
        this.emit('stalled');
    }

    /** 元數據已載入 */
    loadedMetadata(duration: number, videoWidth: number, videoHeight: number): void {
        const currentLoadId = this.loadId;

        this.state.duration = duration;
        this.state.videoWidth = videoWidth;
        this.state.videoHeight = videoHeight;
        this.state.readyState = ReadyState.HAVE_METADATA;

        if (currentLoadId === this.loadId && !this.firedEvents.has('loadedmetadata')) {
            this.firedEvents.add('loadedmetadata');
            this.emit('loadedmetadata');
            this.emit('durationchange');
        }
    }

    /** 第一幀已載入 */
    loadedData(): void {
        const currentLoadId = this.loadId;

        this.state.readyState = ReadyState.HAVE_CURRENT_DATA;

        if (currentLoadId === this.loadId && !this.firedEvents.has('loadeddata')) {
            this.firedEvents.add('loadeddata');
            this.emit('loadeddata');
        }
    }

    /** 可以開始播放 */
    canPlay(): void {
        const currentLoadId = this.loadId;

        this.state.readyState = ReadyState.HAVE_FUTURE_DATA;

        if (currentLoadId === this.loadId && !this.firedEvents.has('canplay')) {
            this.firedEvents.add('canplay');
            this.emit('canplay');
        }
    }

    /** 可以播放到結尾 */
    canPlayThrough(): void {
        const currentLoadId = this.loadId;

        this.state.readyState = ReadyState.HAVE_ENOUGH_DATA;
        this.state.networkState = NetworkState.NETWORK_IDLE;

        // 本地播放時，設置完整緩衝
        if (this.state.duration > 0 && this.state.buffered instanceof TimeRangesImpl) {
            this.state.buffered.setFullyBuffered(this.state.duration);
        }

        if (currentLoadId === this.loadId && !this.firedEvents.has('canplaythrough')) {
            this.firedEvents.add('canplaythrough');
            this.emit('canplaythrough');
            // 載入完成後觸發 suspend
            this.emit('suspend');
        }
    }

    // ===== 播放控制事件 =====

    /** 開始播放 - play 和 playing 事件 */
    play(): void {
        const wasPaused = this.state.paused;
        this.state.paused = false;
        this.state.ended = false;

        if (wasPaused) {
            this.emit('play');
        }
        this.emit('playing');
    }

    /** 暫停播放 - pause 事件 */
    pause(): void {
        if (!this.state.paused) {
            this.state.paused = true;
            this.emit('pause');
        }
    }

    /** 播放結束 - ended 事件 */
    fireEnded(): void {
        if (!this.state.ended) {
            this.state.ended = true;
            this.state.paused = true;
            this.emit('pause');
            this.emit('ended');
        }
    }

    /** 等待數據 - waiting 事件 */
    waiting(): void {
        this.emit('waiting');
    }

    // ===== 搜尋事件 =====

    /** 開始搜尋 */
    startSeek(): void {
        if (!this.state.seeking) {
            this.state.seeking = true;
            this.emit('seeking');
        }
    }

    /** 搜尋完成 */
    endSeek(newTime: number): void {
        if (this.state.seeking) {
            this.state.seeking = false;
            this.state.currentTime = newTime;
            this.emit('seeked');
            this.emit('timeupdate');
        }
    }

    // ===== 時間更新 =====

    /** 更新當前時間 */
    updateTime(time: number): void {
        this.state.currentTime = time;
        this.emit('timeupdate');
    }

    /** 更新時長 */
    updateDuration(duration: number): void {
        if (this.state.duration !== duration) {
            this.state.duration = duration;

            // 更新 buffered（本地播放完整緩衝）
            if (this.state.readyState >= ReadyState.HAVE_ENOUGH_DATA &&
                this.state.buffered instanceof TimeRangesImpl) {
                this.state.buffered.setFullyBuffered(duration);
            }

            this.emit('durationchange');
        }
    }

    // ===== 音量和速率 =====

    /** 更新音量 */
    updateVolume(volume: number, muted: boolean): void {
        if (this.state.volume !== volume || this.state.muted !== muted) {
            this.state.volume = volume;
            this.state.muted = muted;
            this.emit('volumechange');
        }
    }

    /** 更新播放速率 */
    updatePlaybackRate(rate: number): void {
        if (this.state.playbackRate !== rate) {
            this.state.playbackRate = rate;
            this.emit('ratechange');
        }
    }

    // ===== 尺寸更新 =====

    /** 更新視頻尺寸 */
    updateVideoSize(width: number, height: number): void {
        if (this.state.videoWidth !== width || this.state.videoHeight !== height) {
            this.state.videoWidth = width;
            this.state.videoHeight = height;
            this.emit('resize');
        }
    }

    // ===== 狀態同步 =====

    /** 從外部狀態同步（來自 mpv） */
    syncState(externalState: {
        position: number;
        duration: number;
        paused: boolean;
        volume: number;
        playing: boolean;
    }): {
        timeChanged: boolean;
        durationChanged: boolean;
        pausedChanged: boolean;
        volumeChanged: boolean;
        wasEnded: boolean;
    } {
        const prev = {
            currentTime: this.state.currentTime,
            duration: this.state.duration,
            paused: this.state.paused,
            volume: this.state.volume,
            ended: this.state.ended,
        };

        this.state.currentTime = externalState.position;
        this.state.paused = externalState.paused;
        this.state.volume = externalState.volume / 100;

        // 更新 duration（如果有變化）
        if (externalState.duration > 0 && externalState.duration !== this.state.duration) {
            this.state.duration = externalState.duration;

            // 更新緩衝範圍
            if (this.state.buffered instanceof TimeRangesImpl) {
                this.state.buffered.setFullyBuffered(externalState.duration);
            }
        }

        // ended 狀態由 MediaFacade 狀態同步中的 time threshold (0.05s) 判斷

        return {
            timeChanged: prev.currentTime !== this.state.currentTime,
            durationChanged: prev.duration !== this.state.duration,
            pausedChanged: prev.paused !== this.state.paused,
            volumeChanged: prev.volume !== this.state.volume,
            wasEnded: !prev.ended && this.state.ended,
        };
    }

    /** 重置狀態 */
    reset(): void {
        this.loadId++;
        this.firedEvents.clear();
        this.state = this.createInitialState();
    }
}
