/**
 * AdaptiveFpsController - 自適應幀率控制器
 *
 * 監控實際渲染效能，當設備無法達到視頻原生 FPS 時自動降級，
 * 避免在低端設備上浪費資源請求無法處理的幀。
 *
 * 使用場景：
 * - 120fps 高規格素材在一般設備上播放
 * - 4K 視頻在低端設備上播放
 * - 多個視頻同時播放時的資源競爭
 */

export interface FpsControllerConfig {
    /** 降級觸發閾值：實際 FPS < 目標 FPS × threshold 時降級 (default: 0.7) */
    degradationThreshold: number;

    /** 恢復觸發閾值：實際 FPS > 有效 FPS × threshold 時嘗試恢復 (default: 0.95) */
    recoveryThreshold: number;

    /** 穩定時間：需要維持多久才觸發降級/恢復 (ms, default: 1500) */
    stabilityDuration: number;

    /** 最小 FPS：降級的下限，確保至少能看 (default: 12) */
    minimumFps: number;

    /** 樣本窗口大小：用多少個幀來計算移動平均 FPS (default: 30) */
    sampleWindowSize: number;

    /** 是否啟用自動降級 (default: true) */
    enabled: boolean;

    /** 屏幕刷新率上限：超過此值的 FPS 請求沒有意義 (default: auto-detect or 60) */
    screenRefreshRate: number;
}

export interface FpsStats {
    /** 視頻原生 FPS */
    nativeFps: number;

    /** 屏幕刷新率上限 */
    screenRefreshRate: number;

    /** 目標 FPS（min(原生, 屏幕刷新率)，這是理論上能達到的最大值） */
    targetFps: number;

    /** 當前有效 FPS（可能已降級） */
    effectiveFps: number;

    /** 實際測量的 FPS */
    actualFps: number;

    /** 當前降級層級 (0 = 無降級, 1-4 = 降級程度) */
    degradationLevel: number;

    /** 降級百分比 (1.0 = 100%, 0.5 = 50%) */
    degradationRatio: number;

    /** 是否正在降級狀態 */
    isDegraded: boolean;

    /** 是否正在恢復中 */
    isRecovering: boolean;

    /** 是否因屏幕刷新率而被限制 */
    isScreenLimited: boolean;
}

export type FpsDegradationCallback = (stats: FpsStats, reason: string) => void;

/**
 * 降級階梯定義
 * 從 100% 逐步降到 25%，確保平滑過渡
 */
const DEGRADATION_LEVELS = [
    1.0,    // Level 0: 100% (無降級)
    0.75,   // Level 1: 75%
    0.5,    // Level 2: 50%
    0.33,   // Level 3: 33%
    0.25,   // Level 4: 25% (最低)
];

const DEFAULT_CONFIG: FpsControllerConfig = {
    degradationThreshold: 0.7,
    recoveryThreshold: 0.95,
    stabilityDuration: 1500,
    minimumFps: 12,
    sampleWindowSize: 30,
    enabled: false,  // 禁用 JS 端降級，由 C++ 端動態控制
    screenRefreshRate: 0, // 0 = auto-detect
};

/**
 * 偵測屏幕刷新率
 * 通過測量 requestAnimationFrame 的實際間隔來推算
 */
async function detectScreenRefreshRate(): Promise<number> {
    return new Promise((resolve) => {
        const samples: number[] = [];
        let lastTime = 0;
        let frameCount = 0;
        const targetSamples = 10;

        const measure = (timestamp: number) => {
            if (lastTime > 0) {
                const delta = timestamp - lastTime;
                if (delta > 0 && delta < 100) { // 忽略異常值
                    samples.push(delta);
                }
            }
            lastTime = timestamp;
            frameCount++;

            if (samples.length >= targetSamples) {
                // 計算平均間隔並轉換為 FPS
                const avgDelta = samples.reduce((a, b) => a + b, 0) / samples.length;
                const detectedFps = Math.round(1000 / avgDelta);
                // 對齊到常見刷新率: 60, 75, 90, 120, 144, 165, 240
                const commonRates = [60, 75, 90, 120, 144, 165, 240];
                const closest = commonRates.reduce((prev, curr) =>
                    Math.abs(curr - detectedFps) < Math.abs(prev - detectedFps) ? curr : prev
                );
                console.log(`[AdaptiveFps] Screen refresh rate detected: ~${detectedFps}fps → ${closest}Hz`);
                resolve(closest);
            } else if (frameCount < 20) {
                requestAnimationFrame(measure);
            } else {
                // 如果無法測量，默認 60Hz
                console.log('[AdaptiveFps] Could not detect refresh rate, defaulting to 60Hz');
                resolve(60);
            }
        };

        requestAnimationFrame(measure);
    });
}

export class AdaptiveFpsController {
    private config: FpsControllerConfig;

    // 幀率追蹤
    private nativeFps: number = 24;
    private screenRefreshRate: number = 60; // 屏幕刷新率（初始假設 60Hz）
    private screenRefreshRateDetected: boolean = false;
    private frameTimestamps: number[] = [];
    private actualFps: number = 0;

    // 降級狀態
    private currentLevel: number = 0;
    private degradationStartTime: number = 0;
    private recoveryStartTime: number = 0;

    // 回調
    private onDegradation: FpsDegradationCallback | null = null;
    private onRecovery: FpsDegradationCallback | null = null;

    // 統計
    private totalFrames: number = 0;
    private degradedFrames: number = 0;

    // 播放狀態：只有在播放時才收集 FPS 樣本
    private isPaused: boolean = false;

    constructor(config: Partial<FpsControllerConfig> = {}) {
        this.config = { ...DEFAULT_CONFIG, ...config };

        // 如果配置了屏幕刷新率，直接使用；否則異步偵測
        if (this.config.screenRefreshRate > 0) {
            this.screenRefreshRate = this.config.screenRefreshRate;
            this.screenRefreshRateDetected = true;
        } else {
            // 異步偵測屏幕刷新率
            this.detectAndSetScreenRefreshRate();
        }
    }

    /**
     * 異步偵測並設定屏幕刷新率
     */
    private async detectAndSetScreenRefreshRate(): Promise<void> {
        try {
            const rate = await detectScreenRefreshRate();
            this.screenRefreshRate = rate;
            this.screenRefreshRateDetected = true;
            console.log(`[AdaptiveFps] Using screen refresh rate: ${rate}Hz`);
        } catch {
            console.warn('[AdaptiveFps] Failed to detect screen refresh rate, using 60Hz');
            this.screenRefreshRate = 60;
            this.screenRefreshRateDetected = true;
        }
    }

    /**
     * 獲取目標 FPS（考慮屏幕刷新率上限）
     * 這是理論上能達到的最大 FPS
     */
    public getTargetFps(): number {
        return Math.min(this.nativeFps, this.screenRefreshRate);
    }

    /**
     * 獲取屏幕刷新率
     */
    public getScreenRefreshRate(): number {
        return this.screenRefreshRate;
    }

    /**
     * 手動設定屏幕刷新率
     */
    public setScreenRefreshRate(rate: number): void {
        if (rate > 0) {
            this.screenRefreshRate = rate;
            this.screenRefreshRateDetected = true;
            console.log(`[AdaptiveFps] Screen refresh rate manually set to ${rate}Hz`);
        }
    }

    /**
     * 設定視頻原生 FPS
     */
    public setNativeFps(fps: number): void {
        if (fps > 0 && fps !== this.nativeFps) {
            this.nativeFps = fps;
            this.reset();

            const targetFps = this.getTargetFps();
            if (fps > this.screenRefreshRate) {
                console.log(`[AdaptiveFps] Native FPS: ${fps} → capped to ${targetFps}fps (screen: ${this.screenRefreshRate}Hz)`);
            } else {
                console.log(`[AdaptiveFps] Native FPS set to ${fps}`);
            }
        }
    }

    /**
     * 記錄一個幀的渲染完成
     * 應在每次成功渲染幀後調用
     */
    public recordFrame(timestamp: number): void {
        // 暫停狀態下不收集樣本，避免錯誤的 FPS 計算
        if (this.isPaused) {
            return;
        }

        this.totalFrames++;
        if (this.currentLevel > 0) {
            this.degradedFrames++;
        }

        // 加入時間戳
        this.frameTimestamps.push(timestamp);

        // 保持窗口大小
        while (this.frameTimestamps.length > this.config.sampleWindowSize) {
            this.frameTimestamps.shift();
        }

        // 計算實際 FPS
        this.calculateActualFps();

        // 執行降級/恢復決策
        if (this.config.enabled) {
            this.evaluateDegradation(timestamp);
        }
    }

    /**
     * 獲取當前應該使用的有效幀間隔 (ms)
     */
    public getEffectiveFrameInterval(): number {
        const effectiveFps = this.getEffectiveFps();
        return (1000 / effectiveFps) * 0.95; // 95% 留餘量
    }

    /**
     * 獲取當前有效 FPS
     * 考慮：屏幕刷新率上限 + 降級層級 + 最小 FPS 保障
     */
    public getEffectiveFps(): number {
        // 1. 先取目標 FPS（不超過屏幕刷新率）
        const targetFps = this.getTargetFps();

        // 2. 應用降級比例
        const ratio = DEGRADATION_LEVELS[this.currentLevel];
        const degradedFps = targetFps * ratio;

        // 3. 確保不低於最小 FPS
        return Math.max(degradedFps, this.config.minimumFps);
    }

    /**
     * 獲取完整的 FPS 統計資訊
     */
    public getStats(): FpsStats {
        const targetFps = this.getTargetFps();
        const effectiveFps = this.getEffectiveFps();
        const ratio = DEGRADATION_LEVELS[this.currentLevel];

        return {
            nativeFps: this.nativeFps,
            screenRefreshRate: this.screenRefreshRate,
            targetFps,
            effectiveFps,
            actualFps: this.actualFps,
            degradationLevel: this.currentLevel,
            degradationRatio: ratio,
            isDegraded: this.currentLevel > 0,
            isRecovering: this.recoveryStartTime > 0,
            isScreenLimited: this.nativeFps > this.screenRefreshRate,
        };
    }

    /**
     * 設定降級回調
     */
    public onDegradationChange(callback: FpsDegradationCallback): void {
        this.onDegradation = callback;
    }

    /**
     * 設定恢復回調
     */
    public onRecoveryChange(callback: FpsDegradationCallback): void {
        this.onRecovery = callback;
    }

    /**
     * 手動強制降級到指定層級
     */
    public forceDegradation(level: number): void {
        const newLevel = Math.max(0, Math.min(level, DEGRADATION_LEVELS.length - 1));
        if (newLevel !== this.currentLevel) {
            const oldLevel = this.currentLevel;
            this.currentLevel = newLevel;
            console.log(`[AdaptiveFps] Forced degradation: level ${oldLevel} → ${newLevel}`);

            if (this.onDegradation) {
                this.onDegradation(this.getStats(), 'manual');
            }
        }
    }

    /**
     * 重置控制器狀態
     */
    public reset(): void {
        this.frameTimestamps = [];
        this.actualFps = 0;
        this.currentLevel = 0;
        this.degradationStartTime = 0;
        this.recoveryStartTime = 0;
        this.isPaused = false;
        console.log('[AdaptiveFps] Controller reset');
    }

    /**
     * 銷毀控制器，清理所有引用
     * 防止回調函數持有對已銷毀組件的引用導致內存洩漏
     */
    public destroy(): void {
        this.reset();
        this.onDegradation = null;
        this.onRecovery = null;
        console.log('[AdaptiveFps] Controller destroyed');
    }

    /**
     * 暫停 FPS 樣本收集
     * 當視頻暫停、seeking、或其他非正常播放狀態時調用
     * 會清空已收集的時間戳，避免恢復播放後計算出錯誤的 FPS
     */
    public pauseCollection(): void {
        if (this.isPaused) return;
        this.isPaused = true;
        // 清空樣本，避免跨暫停期間的時間戳影響 FPS 計算
        this.frameTimestamps = [];
        this.degradationStartTime = 0;
        this.recoveryStartTime = 0;
    }

    /**
     * 恢復 FPS 樣本收集
     * 當視頻恢復正常播放時調用
     */
    public resumeCollection(): void {
        if (!this.isPaused) return;
        this.isPaused = false;
        // 樣本已在 pause 時清空，恢復後會重新收集
    }

    /**
     * 更新配置
     */
    public updateConfig(config: Partial<FpsControllerConfig>): void {
        this.config = { ...this.config, ...config };

        // 如果禁用了自適應，重置到無降級狀態
        if (!this.config.enabled && this.currentLevel > 0) {
            this.currentLevel = 0;
            console.log('[AdaptiveFps] Disabled - reset to full FPS');
        }
    }

    /**
     * 獲取效能統計摘要（用於 debug/監控）
     */
    public getSummary(): string {
        const stats = this.getStats();

        const screenLimitedNote = stats.isScreenLimited ? ` (capped by ${stats.screenRefreshRate}Hz screen)` : '';

        return `Native: ${stats.nativeFps.toFixed(1)}fps | ` +
               `Target: ${stats.targetFps.toFixed(1)}fps${screenLimitedNote} | ` +
               `Effective: ${stats.effectiveFps.toFixed(1)}fps | ` +
               `Actual: ${stats.actualFps.toFixed(1)}fps | ` +
               `Level: ${stats.degradationLevel}`;
    }

    // ===== Private Methods =====

    private calculateActualFps(): void {
        if (this.frameTimestamps.length < 2) {
            this.actualFps = 0;
            return;
        }

        const first = this.frameTimestamps[0];
        const last = this.frameTimestamps[this.frameTimestamps.length - 1];
        const duration = last - first;

        if (duration > 0) {
            // FPS = (幀數 - 1) / 時間差
            this.actualFps = ((this.frameTimestamps.length - 1) / duration) * 1000;
        }
    }

    private evaluateDegradation(timestamp: number): void {
        // 需要足夠的樣本才能做決策
        if (this.frameTimestamps.length < Math.min(10, this.config.sampleWindowSize)) {
            return;
        }

        const effectiveFps = this.getEffectiveFps();
        const performanceRatio = this.actualFps / effectiveFps;

        // 檢查是否需要降級
        if (performanceRatio < this.config.degradationThreshold) {
            // 開始或繼續降級計時
            if (this.degradationStartTime === 0) {
                this.degradationStartTime = timestamp;
            }

            // 清除恢復計時
            this.recoveryStartTime = 0;

            // 檢查是否達到穩定時間
            if (timestamp - this.degradationStartTime >= this.config.stabilityDuration) {
                this.performDegradation();
                this.degradationStartTime = 0;
            }
        }
        // 檢查是否可以恢復
        else if (performanceRatio >= this.config.recoveryThreshold && this.currentLevel > 0) {
            // 開始或繼續恢復計時
            if (this.recoveryStartTime === 0) {
                this.recoveryStartTime = timestamp;
            }

            // 清除降級計時
            this.degradationStartTime = 0;

            // 檢查是否達到穩定時間
            if (timestamp - this.recoveryStartTime >= this.config.stabilityDuration) {
                this.performRecovery();
                this.recoveryStartTime = 0;
            }
        }
        // 效能正常，清除所有計時器
        else {
            this.degradationStartTime = 0;
            // 只有在效能足夠好時才清除恢復計時
            if (performanceRatio < this.config.recoveryThreshold) {
                this.recoveryStartTime = 0;
            }
        }
    }

    private performDegradation(): void {
        if (this.currentLevel >= DEGRADATION_LEVELS.length - 1) {
            // 已經是最低層級
            console.log(`[AdaptiveFps] Already at minimum level (${this.currentLevel})`);
            return;
        }

        const oldLevel = this.currentLevel;
        this.currentLevel++;

        const stats = this.getStats();
        const reason = `Actual FPS (${this.actualFps.toFixed(1)}) < threshold ` +
                      `(${(stats.effectiveFps * this.config.degradationThreshold).toFixed(1)})`;

        console.log(`[AdaptiveFps] Degraded: level ${oldLevel} → ${this.currentLevel} | ` +
                   `${stats.nativeFps}fps → ${stats.effectiveFps.toFixed(1)}fps | ${reason}`);

        // 清空樣本重新收集（避免舊數據影響新決策）
        this.frameTimestamps = [];

        if (this.onDegradation) {
            this.onDegradation(stats, reason);
        }
    }

    private performRecovery(): void {
        if (this.currentLevel <= 0) {
            return;
        }

        const oldLevel = this.currentLevel;
        this.currentLevel--;

        const stats = this.getStats();
        const reason = `Actual FPS (${this.actualFps.toFixed(1)}) reached recovery threshold`;

        console.log(`[AdaptiveFps] Recovered: level ${oldLevel} → ${this.currentLevel} | ` +
                   `Effective FPS now ${stats.effectiveFps.toFixed(1)}`);

        // 清空樣本重新收集
        this.frameTimestamps = [];

        if (this.onRecovery) {
            this.onRecovery(stats, reason);
        }
    }
}
