/**
 * 主題管理器
 *
 * 提供播放器主題定制功能
 * 支援 CSS 變數注入和預設主題
 */

/**
 * 主題變數類型
 */
export interface ThemeVariables {
    // 主要顏色
    'primary-color'?: string;
    'primary-hover-color'?: string;

    // 背景顏色
    'controls-bg'?: string;
    'menu-bg'?: string;
    'tooltip-bg'?: string;

    // 文字顏色
    'text-color'?: string;
    'text-secondary-color'?: string;

    // 進度條
    'progress-bg'?: string;
    'progress-buffered-color'?: string;
    'progress-played-color'?: string;

    // 按鈕
    'button-color'?: string;
    'button-hover-color'?: string;
    'button-active-color'?: string;

    // 邊框和陰影
    'border-color'?: string;
    'shadow-color'?: string;

    // 尺寸
    'controls-height'?: string;
    'button-size'?: string;
    'icon-size'?: string;

    // 字體
    'font-family'?: string;
    'font-size'?: string;

    // 動畫
    'transition-duration'?: string;

    // 自定義變數
    [key: `--${string}`]: string | undefined;
}

/**
 * 主題定義
 */
export interface Theme {
    /** 主題名稱 */
    name: string;
    /** 主題變數 */
    variables: ThemeVariables;
}

/**
 * 主題管理器接口
 */
export interface IThemeManager {
    /**
     * 應用主題
     * @param theme - 主題定義或主題名稱
     */
    apply(theme: Theme | string): void;

    /**
     * 設置單個 CSS 變數
     * @param name - 變數名稱
     * @param value - 變數值
     */
    setVariable(name: string, value: string): void;

    /**
     * 獲取當前主題名稱
     */
    getCurrentTheme(): string | null;

    /**
     * 重置為默認主題
     */
    reset(): void;

    /**
     * 註冊預設主題
     * @param theme - 主題定義
     */
    registerTheme(theme: Theme): void;

    /**
     * 獲取所有已註冊的主題名稱
     */
    getThemeNames(): string[];
}

