/**
 * CSS 變數前綴
 */
const CSS_VAR_PREFIX = '--vp-';

/**
 * 主題管理器實現
 */
export class ThemeManager implements IThemeManager {
    private shadowRoot: ShadowRoot | null = null;
    private currentTheme: string | null = null;
    private registeredThemes: Map<string, Theme> = new Map();
    private styleElement: HTMLStyleElement | null = null;

    constructor(shadowRoot?: ShadowRoot) {
        this.shadowRoot = shadowRoot ?? null;

        // 註冊預設主題
        this.registerTheme(darkTheme);
        this.registerTheme(lightTheme);
    }

    /**
     * 設置 Shadow Root（如果構造時未提供）
     */
    setShadowRoot(shadowRoot: ShadowRoot): void {
        this.shadowRoot = shadowRoot;
    }

    /**
     * 確保樣式元素存在
     */
    private ensureStyleElement(): HTMLStyleElement {
        if (this.styleElement) {
            return this.styleElement;
        }

        this.styleElement = document.createElement('style');
        this.styleElement.setAttribute('data-theme', 'custom');

        if (this.shadowRoot) {
            this.shadowRoot.appendChild(this.styleElement);
        } else {
            document.head.appendChild(this.styleElement);
        }

        return this.styleElement;
    }

    /**
     * 生成 CSS 變數字符串
     */
    private generateCSSVariables(variables: ThemeVariables): string {
        const lines: string[] = [];

        for (const [key, value] of Object.entries(variables)) {
            if (value === undefined) continue;

            // 處理自定義變數（以 -- 開頭）
            const varName = key.startsWith('--') ? key : `${CSS_VAR_PREFIX}${key}`;
            lines.push(`  ${varName}: ${value};`);
        }

        return `:host {\n${lines.join('\n')}\n}`;
    }

    apply(theme: Theme | string): void {
        let themeObj: Theme;

        if (typeof theme === 'string') {
            const registered = this.registeredThemes.get(theme);
            if (!registered) {
                console.warn(`[ThemeManager] Theme "${theme}" not found`);
                return;
            }
            themeObj = registered;
        } else {
            themeObj = theme;
        }

        const styleEl = this.ensureStyleElement();
        styleEl.textContent = this.generateCSSVariables(themeObj.variables);
        this.currentTheme = themeObj.name;

        console.log(`[ThemeManager] Applied theme: ${themeObj.name}`);
    }

    setVariable(name: string, value: string): void {
        const target = this.shadowRoot ?? document.documentElement;
        const varName = name.startsWith('--') ? name : `${CSS_VAR_PREFIX}${name}`;
        (target as HTMLElement).style.setProperty(varName, value);
    }

    getCurrentTheme(): string | null {
        return this.currentTheme;
    }

    reset(): void {
        if (this.styleElement) {
            this.styleElement.textContent = '';
        }
        this.currentTheme = null;
    }

    registerTheme(theme: Theme): void {
        this.registeredThemes.set(theme.name, theme);
    }

    getThemeNames(): string[] {
        return [...this.registeredThemes.keys()];
    }

    /**
     * 獲取已註冊的主題
     */
    getTheme(name: string): Theme | undefined {
        return this.registeredThemes.get(name);
    }

    /**
     * 銷毀主題管理器
     */
    destroy(): void {
        if (this.styleElement) {
            this.styleElement.remove();
            this.styleElement = null;
        }
        this.currentTheme = null;
    }
}

/**
 * 創建主題管理器實例
 */
export function createThemeManager(shadowRoot?: ShadowRoot): IThemeManager {
    return new ThemeManager(shadowRoot);
}
