/**
 * AttributeObserver - HTML 屬性變化處理
 *
 * 負責：
 * - 定義觀察的屬性列表
 * - 處理屬性變化回調
 * - 將屬性變化映射到相應的行為
 */

import type { ControlsMode } from './ControlsManager';

/**
 * 屬性變化處理器
 */
export interface AttributeHandlers {
    /** 處理 src 變化 */
    onSrcChange: (src: string | null) => void;
    /** 處理 muted 變化 */
    onMutedChange: (muted: boolean) => void;
    /** 處理 playbackrate 變化 */
    onPlaybackRateChange: (rate: number) => void;
    /** 處理 controls-mode 變化 */
    onControlsModeChange: (mode: ControlsMode) => void;
    /** 獲取元素是否已連接到 DOM */
    isConnected: () => boolean;
    /** 獲取控制列是否已初始化 */
    isControlsInitialized: () => boolean;
}

/**
 * 觀察的屬性列表
 */
export const OBSERVED_ATTRIBUTES = [
    'src',
    'loop',
    'autoplay',
    'muted',
    'controls',
    'controls-mode',
    'poster',
    'width',
    'height',
    'playbackrate',
] as const;

export type ObservedAttribute = typeof OBSERVED_ATTRIBUTES[number];

/**
 * 屬性觀察器
 */
export class AttributeObserver {
    private handlers: AttributeHandlers;
    private host: HTMLElement;

    constructor(host: HTMLElement, handlers: AttributeHandlers) {
        this.host = host;
        this.handlers = handlers;
    }

    /**
     * 處理屬性變化
     * 對應 Custom Element 的 attributeChangedCallback
     */
    handleChange(name: string, oldValue: string | null, newValue: string | null): void {
        if (oldValue === newValue) return;

        switch (name) {
            case 'src':
                // 允許離線載入（不檢查 isConnected）
                if (newValue) {
                    this.handlers.onSrcChange(newValue);
                }
                break;

            case 'loop':
                // loop 由 getter 處理，這裡不需要額外操作
                break;

            case 'autoplay':
                // autoplay 在 load 時處理
                break;

            case 'muted':
                this.handlers.onMutedChange(newValue !== null);
                break;

            case 'width':
                if (newValue) {
                    this.host.style.width = `${newValue}px`;
                }
                break;

            case 'height':
                if (newValue) {
                    this.host.style.height = `${newValue}px`;
                }
                break;

            case 'playbackrate':
                if (newValue) {
                    this.handlers.onPlaybackRateChange(parseFloat(newValue));
                }
                break;

            case 'controls':
                // controls 屬性由 CSS :host([controls]) 處理
                break;

            case 'controls-mode':
                if (newValue && ['always', 'auto', 'none'].includes(newValue)) {
                    // 只有已連接 DOM 且初始化後才應用
                    if (this.handlers.isConnected() && this.handlers.isControlsInitialized()) {
                        this.handlers.onControlsModeChange(newValue as ControlsMode);
                    }
                }
                break;

            case 'poster':
                // poster 目前未實現
                break;
        }
    }
}

/**
 * 創建屬性觀察器並綁定到 Custom Element
 *
 * 用法：
 * ```typescript
 * class MyElement extends HTMLElement {
 *     private attributeObserver: AttributeObserver;
 *
 *     static get observedAttributes() {
 *         return OBSERVED_ATTRIBUTES;
 *     }
 *
 *     constructor() {
 *         super();
 *         this.attributeObserver = new AttributeObserver(this, {
 *             onSrcChange: (src) => { ... },
 *             // ...
 *         });
 *     }
 *
 *     attributeChangedCallback(name, oldValue, newValue) {
 *         this.attributeObserver.handleChange(name, oldValue, newValue);
 *     }
 * }
 * ```
 */
