/**
 * ControlsManager - 控制列 UI 管理
 *
 * 負責：
 * - 控制列顯示/隱藏邏輯
 * - 控制列模式管理 (always/auto/none)
 * - 控制列相關事件綁定
 * - CSS 狀態類別管理
 */

export type ControlsMode = 'always' | 'auto' | 'none';

/**
 * ControlsManager 配置
 */
export interface ControlsManagerConfig {
    /** Host 元素（MpvVideoElement 自身） */
    host: HTMLElement;
    /** Shadow Root */
    shadowRoot: ShadowRoot;
    /** 視頻包裝元素 */
    videoWrapper: HTMLDivElement;
    /** 控制列元素 */
    controlsEl: HTMLDivElement;
    /** 切換播放/暫停 */
    toggle: () => void;
    /** 切換全螢幕 */
    toggleFullscreen: () => void;
    /** 獲取音量 */
    getVolume: () => number;
}

/**
 * 控制列管理器
 */
export class ControlsManager {
    private config: ControlsManagerConfig;

    // 控制列狀態
    private _mode: ControlsMode = 'auto';
    private _userMode: ControlsMode = 'auto';
    private _initialized: boolean = false;
    private _visible: boolean = true;
    private hideTimeout: number | null = null;

    // 事件清理函數數組（用於 destroy 時移除所有監聽器）
    private cleanups: Array<() => void> = [];

    // 自動隱藏延遲（毫秒）
    private static readonly HIDE_DELAY = 3000;

    constructor(config: ControlsManagerConfig) {
        this.config = config;
    }

    /**
     * 初始化控制列（只應在 connectedCallback 中調用一次）
     */
    initialize(): void {
        if (this._initialized) return;
        this._initialized = true;

        this.bindCoreEvents();
        this.bindStateClassEvents();
        this.applyMode();
    }

    /**
     * 獲取控制列模式
     */
    get mode(): ControlsMode {
        return this._mode;
    }

    /**
     * 設置控制列模式
     */
    set mode(value: ControlsMode) {
        if (['always', 'auto', 'none'].includes(value)) {
            this._userMode = value;
            // In fullscreen, force 'always' → 'auto' for auto-hide behavior
            this._mode = (value === 'always' && !!document.fullscreenElement) ? 'auto' : value;
            if (this._initialized) {
                this.applyMode();
                if (this._mode === 'auto') {
                    this.scheduleHide();
                }
            }
        }
    }

    /**
     * 獲取用戶設定的控制列模式（不受全螢幕覆蓋影響）
     */
    get userMode(): ControlsMode {
        return this._userMode;
    }

    /**
     * 控制列是否可見
     */
    get visible(): boolean {
        return this._visible;
    }

    /**
     * 是否已初始化
     */
    get initialized(): boolean {
        return this._initialized;
    }

    /**
     * 顯示控制列
     */
    show(): void {
        this._visible = true;
        this.config.host.classList.remove('controls-hidden');
    }

    /**
     * 隱藏控制列
     */
    hide(): void {
        if (this._mode === 'auto') {
            this._visible = false;
            this.config.host.classList.add('controls-hidden');
        }
    }

    /**
     * 取消隱藏計時器
     */
    cancelHide(): void {
        if (this.hideTimeout) {
            clearTimeout(this.hideTimeout);
            this.hideTimeout = null;
        }
    }

    /**
     * 排程隱藏控制列
     */
    scheduleHide(): void {
        this.cancelHide();
        if (this._mode === 'auto') {
            this.hideTimeout = window.setTimeout(() => {
                this.hide();
            }, ControlsManager.HIDE_DELAY);
        }
    }

    /**
     * 應用控制列模式
     */
    applyMode(): void {
        const { host } = this.config;

        host.classList.remove('controls-hidden', 'controls-none');

        switch (this._mode) {
            case 'always':
                this._visible = true;
                break;
            case 'none':
                host.classList.add('controls-none');
                this._visible = false;
                break;
            case 'auto':
            default:
                this._visible = true;
                break;
        }
    }

    /**
     * 銷毀並清理資源
     */
    destroy(): void {
        this.cancelHide();

        // 執行所有清理函數（移除事件監聽器）
        for (const cleanup of this.cleanups) {
            cleanup();
        }
        this.cleanups = [];

        this._initialized = false;
    }

    // ===== 內部方法 =====

    /**
     * 添加事件監聽器並追蹤以便清理
     */
    private on<K extends keyof HTMLElementEventMap>(
        target: EventTarget,
        event: K | string,
        handler: EventListener
    ): void {
        target.addEventListener(event, handler);
        this.cleanups.push(() => target.removeEventListener(event, handler));
    }

    /**
     * 綁定控制列核心事件
     */
    private bindCoreEvents(): void {
        const { host, videoWrapper, controlsEl } = this.config;

        // 點擊元素獲得焦點（快捷鍵需要）
        this.on(host, 'mousedown', () => {
            host.focus();
        });

        // 點擊視頻切換播放
        this.on(videoWrapper, 'click', () => this.config.toggle());

        // 攔截工具列雙擊事件，不讓它冒泡到外層
        this.on(controlsEl, 'dblclick', (e: Event) => {
            e.stopPropagation();
        });

        // 控制列自動隱藏事件（只在 auto 模式下生效）
        this.on(videoWrapper, 'mousemove', () => {
            if (this._mode === 'auto') {
                this.show();
                this.scheduleHide();
            }
        });

        this.on(controlsEl, 'mouseenter', () => {
            if (this._mode === 'auto') {
                this.cancelHide();
                this.show();
            }
        });

        this.on(host, 'mouseleave', () => {
            if (this._mode === 'auto') {
                this.scheduleHide();
            }
        });

        // 初始排程隱藏
        if (this._mode === 'auto') {
            this.scheduleHide();
        }
    }

    /**
     * 綁定狀態類別事件（供 CSS 使用）
     */
    private bindStateClassEvents(): void {
        const { host } = this.config;

        // 播放狀態
        this.on(host, 'play', () => host.classList.toggle('playing', true));
        this.on(host, 'pause', () => host.classList.toggle('playing', false));
        this.on(host, 'ended', () => host.classList.remove('playing'));

        // 載入狀態
        this.on(host, 'loadedmetadata', () => host.classList.remove('no-source'));
        this.on(host, 'emptied', () => host.classList.add('no-source'));
        this.on(host, 'loadstart', () => host.classList.add('loading'));
        this.on(host, 'error', (e: Event) => {
            host.classList.remove('loading');
            host.classList.add('error');
            const message = (e as ErrorEvent).message
                || (host as any).error?.message
                || 'Unknown error';
            this.config.videoWrapper.setAttribute('data-error', message);
        });

        // 搜尋/緩衝狀態
        this.on(host, 'seeking', () => host.classList.add('seeking'));
        this.on(host, 'seeked', () => host.classList.remove('seeking'));
        this.on(host, 'waiting', () => host.classList.add('buffering'));
        this.on(host, 'canplay', () => {
            host.classList.remove('loading', 'buffering', 'error');
            this.config.videoWrapper.removeAttribute('data-error');
        });

        // 音量狀態
        this.on(host, 'volumechange', () => {
            host.classList.toggle('muted', this.config.getVolume() === 0);
        });

        // 全螢幕狀態追蹤（注意：這是 document 級別的監聽器，也需要正確清理）
        this.on(document, 'fullscreenchange', () => {
            const isFullscreen = !!document.fullscreenElement;
            host.classList.toggle('fullscreen', isFullscreen);

            if (isFullscreen) {
                // Enter fullscreen: force 'always' → 'auto' for auto-hide
                if (this._userMode === 'always') {
                    this._mode = 'auto';
                    this.applyMode();
                    this.scheduleHide();
                }
            } else {
                // Exit fullscreen: restore user's original mode
                this._mode = this._userMode;
                this.cancelHide();
                this.applyMode();
            }
        });
    }
}
